css:
@property --apf-drive-fill { syntax: '<percentage>'; inherits: true; initial-value: 0%; }
@keyframes apf-drive-in { from { opacity: 0; translate: 0 8px; scale: .985; } }
@keyframes apf-drive-pulse { 40% { scale: 1.06; } }
@keyframes apf-drive-fillup { from { --apf-drive-fill: 0%; } }

.apf-drive {
  /* re-theme with these four */
  --apf-drive-bg: oklch(0.986 0.004 95);
  --apf-drive-ink: oklch(0.24 0.014 70);
  --apf-drive-accent: oklch(0.52 0.115 158);
  --apf-drive-warn: oklch(0.57 0.19 29);

  --apf-drive-panel: color-mix(in oklch, var(--apf-drive-bg), var(--apf-drive-ink) 3.5%);
  --apf-drive-raise: color-mix(in oklch, var(--apf-drive-bg), white 60%);
  --apf-drive-line: color-mix(in oklch, var(--apf-drive-ink) 10%, transparent);
  --apf-drive-line2: color-mix(in oklch, var(--apf-drive-ink) 17%, transparent);
  --apf-drive-mute: color-mix(in oklch, var(--apf-drive-ink) 58%, var(--apf-drive-bg));
  --apf-drive-faint: color-mix(in oklch, var(--apf-drive-ink) 36%, var(--apf-drive-bg));
  --apf-drive-tint: color-mix(in oklch, var(--apf-drive-accent) 11%, var(--apf-drive-bg));
  --apf-drive-tint2: color-mix(in oklch, var(--apf-drive-accent) 20%, var(--apf-drive-bg));
  --apf-drive-hover: color-mix(in oklch, var(--apf-drive-ink) 4.5%, transparent);
  --apf-drive-spring: linear(0, 0.06 3%, 0.24 7.5%, 0.53 13%, 0.82 19%, 0.97 25%, 1.04 30%, 1.05 35%, 1.03 42%, 1.005 52%, 0.998 64%, 1);
  --apf-drive-out: cubic-bezier(.2, .8, .2, 1);
  --apf-drive-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --apf-drive-sw: 236px;
  --apf-drive-pw: 304px;

  position: relative; width: 100%; height: var(--apf-drive-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--apf-drive-bg); color: var(--apf-drive-ink);
  font: 13px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
  border-radius: 14px; color-scheme: light; accent-color: var(--apf-drive-accent);
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :where(button, input) { font: inherit; color: inherit; }
  & :where(button) { cursor: pointer; background: none; border: 0; padding: 0; }
  & :where(svg) { fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & :focus-visible { outline: 2px solid var(--apf-drive-accent); outline-offset: 2px; }
  & kbd {
    font: 600 10px/1 var(--apf-drive-mono); padding: 3px 5px 2px; border-radius: 5px; white-space: nowrap;
    border: 1px solid var(--apf-drive-line2); border-bottom-width: 2px; color: var(--apf-drive-mute);
    background: var(--apf-drive-raise);
  }
  & .apf-drive-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
}

.apf-drive-app {
  height: 100%; display: grid;
  grid-template-columns: var(--apf-drive-sw) minmax(0, 1fr) var(--apf-drive-pw);
  grid-template-rows: auto minmax(0, 1fr) auto;
  grid-template-areas: "side top top" "side main pane" "side status status";
  transition: grid-template-columns .55s var(--apf-drive-spring);
}
.apf-drive[data-pane="closed"] .apf-drive-app { grid-template-columns: var(--apf-drive-sw) minmax(0, 1fr) 0px; }

/* ── sidebar ── */
.apf-drive-side {
  grid-area: side; min-height: 0; display: flex; flex-direction: column; gap: 4px;
  padding: 16px 12px 14px; background: var(--apf-drive-panel); border-right: 1px solid var(--apf-drive-line);
  border-radius: 14px 0 0 14px; overflow: hidden;
}
.apf-drive-brand {
  display: flex; gap: 10px; align-items: center; padding: 0 6px 14px;
  & svg { width: 30px; height: 30px; padding: 6px; border-radius: 9px; flex: none; color: var(--apf-drive-bg); background: var(--apf-drive-ink); stroke-width: 2; }
  & b { display: block; font-size: 14px; font-weight: 680; letter-spacing: -.015em; }
  & span { color: var(--apf-drive-mute); font-size: 12px; }
}
.apf-drive-new {
  display: flex; align-items: center; gap: 9px; margin: 0 0 12px; padding: 9px 10px 9px 11px;
  border-radius: 10px; background: var(--apf-drive-raise); border: 1px solid var(--apf-drive-line2);
  box-shadow: 0 1px 2px color-mix(in oklch, var(--apf-drive-ink) 8%, transparent);
  font-weight: 600; transition: box-shadow .25s var(--apf-drive-out), translate .25s var(--apf-drive-out);
  & svg { width: 18px; height: 18px; color: var(--apf-drive-accent); }
  & kbd { margin-left: auto; }
  &:hover { translate: 0 -1px; box-shadow: 0 6px 16px -6px color-mix(in oklch, var(--apf-drive-ink) 22%, transparent); }
  &:active { translate: 0 0; }
}
.apf-drive-places { display: grid; gap: 1px; }
.apf-drive-place, .apf-drive-node > .apf-drive-row {
  display: flex; align-items: center; gap: 9px; width: 100%; min-height: 32px; padding: 0 10px;
  border-radius: 8px; text-align: left; color: var(--apf-drive-ink);
  transition: background-color .15s, color .15s;
  & svg { width: 17px; height: 17px; flex: none; color: var(--apf-drive-mute); }
  & .apf-drive-n { margin-left: auto; font: 500 11px/1 system-ui; font-variant-numeric: tabular-nums; color: var(--apf-drive-faint); }
  &:hover { background: var(--apf-drive-hover); }
  &[aria-current="true"] { background: var(--apf-drive-tint2); font-weight: 620; & svg { color: var(--apf-drive-accent); } }
  &.is-drop { background: var(--apf-drive-accent); color: var(--apf-drive-bg); & svg, & .apf-drive-n { color: inherit; } }
}
.apf-drive-treehead {
  margin: 14px 10px 4px; font-size: 10.5px; font-weight: 650; letter-spacing: .09em; text-transform: uppercase; color: var(--apf-drive-faint);
}
.apf-drive-tree {
  list-style: none; margin: 0; padding: 0; min-height: 0; flex: 1; overflow: auto; scrollbar-width: thin;
  & ul { list-style: none; margin: 0; padding: 0; }
  & .apf-drive-node > .apf-drive-row { padding-left: calc(6px + var(--d, 0) * 16px); min-height: 30px; gap: 4px; }
  & .apf-drive-tw {
    width: 18px; height: 18px; display: grid; place-items: center; border-radius: 5px; flex: none;
    & svg { width: 12px; height: 12px; transition: rotate .3s var(--apf-drive-spring); }
    &:hover { background: var(--apf-drive-hover); }
  }
  & .apf-drive-node[data-open="true"] > .apf-drive-row .apf-drive-tw svg { rotate: 90deg; }
  & .apf-drive-node[data-open="false"] > ul { display: none; }
  & .apf-drive-tw.is-leaf { visibility: hidden; }
  & .apf-drive-row .apf-drive-fo { color: var(--apf-drive-accent); }
  & .apf-drive-row span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
}
.apf-drive-quota {
  margin-top: 10px; padding: 12px 10px 2px; border-top: 1px solid var(--apf-drive-line);
  & .apf-drive-quotarow { display: flex; justify-content: space-between; font-size: 12px; color: var(--apf-drive-mute); & b { color: var(--apf-drive-ink); font-weight: 650; font-variant-numeric: tabular-nums; } }
}
.apf-drive-bar {
  display: flex; height: 7px; margin: 8px 0 9px; border-radius: 99px; overflow: hidden; gap: 2px;
  background: var(--apf-drive-line);
  & i { display: block; height: 100%; flex: var(--w) 0 0; background: var(--k); border-radius: 2px; transition: flex-grow .6s var(--apf-drive-spring); }
}
.apf-drive-legend {
  display: flex; flex-wrap: wrap; gap: 3px 10px; font-size: 11px; color: var(--apf-drive-mute); font-variant-numeric: tabular-nums;
  & span { display: inline-flex; align-items: center; gap: 5px; }
  & span::before { content: ""; width: 7px; height: 7px; border-radius: 2px; background: var(--k); }
}

/* generated thumbnails carry their own strokes; nothing inherits the icon stroke */
.apf-drive-art { stroke: none; }

/* kind colours */
.apf-drive [data-kind="folder"] { --k: var(--apf-drive-accent); }
.apf-drive [data-kind="pdf"] { --k: oklch(0.58 0.17 29); }
.apf-drive [data-kind="img"] { --k: oklch(0.62 0.13 230); }
.apf-drive [data-kind="sheet"] { --k: oklch(0.58 0.13 150); }
.apf-drive [data-kind="doc"] { --k: oklch(0.55 0.14 262); }
.apf-drive [data-kind="model"] { --k: oklch(0.68 0.15 62); }
.apf-drive [data-kind="video"] { --k: oklch(0.52 0.16 330); }

/* ── top bar ── */
.apf-drive-top {
  grid-area: top; display: flex; align-items: center; gap: 12px; padding: 12px 16px 10px; min-width: 0;
  border-bottom: 1px solid var(--apf-drive-line);
}
.apf-drive-icon {
  width: 32px; height: 32px; display: grid; place-items: center; border-radius: 8px; flex: none; color: var(--apf-drive-mute);
  transition: background-color .15s, color .15s;
  & svg { width: 18px; height: 18px; }
  &:hover { background: var(--apf-drive-hover); color: var(--apf-drive-ink); }
  &[aria-pressed="true"] { color: var(--apf-drive-accent); background: var(--apf-drive-tint); }
}
.apf-drive-menu, .apf-drive-back { display: none; }
.apf-drive-crumbs {
  display: flex; align-items: center; min-width: 0; flex: 1; gap: 2px; overflow: hidden;
  & button {
    padding: 4px 7px; border-radius: 7px; white-space: nowrap; color: var(--apf-drive-mute); font-size: 13px;
    transition: background-color .15s, color .15s;
    &:hover { background: var(--apf-drive-hover); color: var(--apf-drive-ink); }
    &.is-drop { background: var(--apf-drive-accent); color: var(--apf-drive-bg); }
  }
  & button:last-of-type {
    color: var(--apf-drive-ink); font-size: clamp(15px, 1.5cqi, 18px); font-weight: 680; letter-spacing: -.02em;
    overflow: hidden; text-overflow: ellipsis; min-width: 70px; flex: 0 1 auto;
  }
  & button:not(:last-of-type) { overflow: hidden; text-overflow: ellipsis; min-width: 0; flex: 0 1 auto; }
  & svg { width: 14px; height: 14px; flex: none; color: var(--apf-drive-faint); }
}
.apf-drive-search {
  display: flex; align-items: center; gap: 7px; height: 34px; padding: 0 7px 0 10px; width: clamp(180px, 26cqi, 300px);
  border-radius: 9px; background: var(--apf-drive-panel); border: 1px solid transparent;
  transition: border-color .15s, background-color .15s, width .35s var(--apf-drive-out);
  & svg { width: 16px; height: 16px; flex: none; color: var(--apf-drive-mute); }
  & input { flex: 1; min-width: 0; border: 0; background: none; outline: none; font-size: 13px; }
  & input::placeholder { color: var(--apf-drive-faint); }
  & input::-webkit-search-cancel-button { display: none; }
  &:focus-within { border-color: var(--apf-drive-accent); background: var(--apf-drive-raise); }
  &:has(input:not(:placeholder-shown)) kbd { display: none; }
}
.apf-drive-tools { display: flex; align-items: center; gap: 8px; flex: none; }
.apf-drive-sort, .apf-drive-seg {
  display: flex; padding: 2px; gap: 2px; border-radius: 9px; background: var(--apf-drive-panel);
  & button {
    height: 28px; padding: 0 9px; border-radius: 7px; font-size: 12px; color: var(--apf-drive-mute); display: inline-flex; align-items: center; gap: 4px;
    transition: background-color .15s, color .15s, box-shadow .15s;
    &:hover { color: var(--apf-drive-ink); }
    & svg { width: 16px; height: 16px; }
  }
  & button[aria-pressed="true"], & button[aria-checked="true"] {
    background: var(--apf-drive-raise); color: var(--apf-drive-ink); font-weight: 600;
    box-shadow: 0 1px 2px color-mix(in oklch, var(--apf-drive-ink) 14%, transparent);
  }
}
.apf-drive-seg button { padding: 0 6px; }
.apf-drive [data-sort][aria-pressed="true"]::after {
  content: ""; width: 7px; height: 7px; margin-left: 1px; border: solid currentColor; border-width: 0 1.6px 1.6px 0;
  rotate: 45deg; translate: 0 -2px; transition: rotate .3s var(--apf-drive-spring), translate .3s var(--apf-drive-spring);
}
.apf-drive [data-sort][data-dir="desc"]::after { rotate: 225deg; translate: 0 2px; }

/* ── main ── */
.apf-drive-main { grid-area: main; min-height: 0; min-width: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); position: relative; }
.apf-drive-bulk {
  display: grid; grid-template-columns: auto auto minmax(0, 1fr); align-items: center; gap: 6px;
  margin: 0 16px; padding: 0 6px; height: 0; overflow: hidden; border-radius: 10px;
  background: var(--apf-drive-ink); color: var(--apf-drive-bg); opacity: 0; translate: 0 -6px;
  transition: height .35s var(--apf-drive-spring), margin .35s var(--apf-drive-spring), opacity .2s, translate .35s var(--apf-drive-spring);
  & .apf-drive-icon { color: inherit; width: 30px; height: 30px; &:hover { background: color-mix(in oklch, var(--apf-drive-bg) 14%, transparent); } }
  & .apf-drive-bulkn { font-weight: 620; font-variant-numeric: tabular-nums; white-space: nowrap; & small { font-weight: 450; opacity: .7; font-size: 12px; margin-left: 6px; } }
  & .apf-drive-bulkbtns { display: flex; justify-content: flex-end; gap: 2px; min-width: 0; }
  & .apf-drive-bulkbtns button {
    display: inline-flex; align-items: center; gap: 6px; height: 30px; padding: 0 9px; border-radius: 7px; font-size: 12.5px;
    &:hover { background: color-mix(in oklch, var(--apf-drive-bg) 14%, transparent); }
    & svg { width: 16px; height: 16px; }
    & kbd { background: none; color: inherit; opacity: .6; border-color: color-mix(in oklch, var(--apf-drive-bg) 30%, transparent); }
  }
  & :focus-visible { outline-color: var(--apf-drive-bg); }
}
.apf-drive[data-sel] .apf-drive-bulk { height: 42px; margin: 10px 16px 0; opacity: 1; translate: 0 0; }
.apf-drive[data-sel="1"] [data-act="rename"] { display: inline-flex; }
.apf-drive:not([data-sel="1"]) [data-act="rename"] { display: none; }

.apf-drive-scroll {
  position: relative; min-height: 0; overflow: auto; padding: 14px 16px 24px; scrollbar-width: thin; overscroll-behavior: contain;
  touch-action: pan-y; user-select: none; -webkit-user-select: none;
}
.apf-drive-sheet { display: block; }
.apf-drive-lhead { display: none; }
.apf-drive-items {
  display: grid; gap: 12px; grid-template-columns: repeat(auto-fill, minmax(clamp(132px, 13.5cqi, 172px), 1fr)); outline: none;
}
.apf-drive-items[data-enter] > * { animation: apf-drive-in .5s var(--apf-drive-out) both; animation-delay: calc(min(var(--i, 0), 18) * 22ms); }
.apf-drive-sec {
  grid-column: 1 / -1; margin: 6px 2px -2px; font-size: 12px; font-weight: 640; color: var(--apf-drive-mute); letter-spacing: .01em;
  &:first-child { margin-top: 0; }
}

.apf-drive-item {
  position: relative; display: grid; min-width: 0; outline: none; cursor: default;
  grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "thumb thumb" "nm nm" "mod size";
  padding: 6px 6px 10px; border-radius: 12px; background: var(--apf-drive-raise);
  border: 1px solid var(--apf-drive-line);
  transition: background-color .18s, border-color .18s, box-shadow .25s var(--apf-drive-out), opacity .2s, scale .35s var(--apf-drive-spring);
  &:hover { border-color: var(--apf-drive-line2); box-shadow: 0 8px 22px -14px color-mix(in oklch, var(--apf-drive-ink) 45%, transparent); }
  &[aria-selected="true"] {
    background: var(--apf-drive-tint); border-color: color-mix(in oklch, var(--apf-drive-accent) 55%, transparent);
    box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--apf-drive-accent) 55%, transparent);
  }
  &:focus-visible { outline: 2px solid var(--apf-drive-accent); outline-offset: 2px; }
  &.is-drop { background: var(--apf-drive-tint2); border-color: var(--apf-drive-accent); scale: 1.03; }
  &.is-lifted { opacity: .4; }
  &.is-hidden { display: none; }
}
.apf-drive-thumb {
  grid-area: thumb; aspect-ratio: 16 / 11; border-radius: 8px; overflow: hidden; margin-bottom: 9px;
  background: var(--apf-drive-panel); position: relative;
  & svg { display: block; width: 100%; height: 100%; stroke-width: 1; }
}
.apf-drive-nm {
  grid-area: nm; display: flex; align-items: center; gap: 7px; min-width: 0; padding: 0 4px;
  & .apf-drive-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: 560; min-width: 0; }
  & .apf-drive-ki { width: 16px; height: 16px; flex: none; color: var(--k); }
  & .apf-drive-st { width: 14px; height: 14px; flex: none; color: oklch(0.72 0.15 75); fill: currentColor; margin-left: auto; }
}
.apf-drive-ren {
  flex: 1; min-width: 0; height: 24px; margin: -3px 0; padding: 0 6px; border-radius: 6px; font-weight: 560;
  border: 1.5px solid var(--apf-drive-accent); background: var(--apf-drive-raise); outline: none;
}
.apf-drive-own { display: none; }
.apf-drive-mod, .apf-drive-size { font-size: 11.5px; color: var(--apf-drive-mute); padding: 3px 4px 0; white-space: nowrap; font-variant-numeric: tabular-nums; overflow: hidden; text-overflow: ellipsis; }
.apf-drive-mod { grid-area: mod; }
.apf-drive-size { grid-area: size; }
.apf-drive-check {
  position: absolute; left: 12px; top: 12px; width: 22px; height: 22px; border-radius: 50%; display: grid; place-items: center;
  background: color-mix(in oklch, var(--apf-drive-raise) 88%, transparent); border: 1.5px solid var(--apf-drive-line2);
  color: transparent; opacity: 0; scale: .7; transition: opacity .18s, scale .3s var(--apf-drive-spring), background-color .15s;
  & svg { width: 14px; height: 14px; stroke-width: 2.4; }
}
.apf-drive-item:hover .apf-drive-check, .apf-drive-items:has([aria-selected="true"]) .apf-drive-check { opacity: 1; scale: 1; }
.apf-drive-item[aria-selected="true"] .apf-drive-check { background: var(--apf-drive-accent); border-color: var(--apf-drive-accent); color: var(--apf-drive-bg); }

/* folders in grid: compact chips */
.apf-drive-item[data-kind="folder"] {
  grid-template-areas: "nm nm"; padding: 0 10px 0 12px; min-height: 48px; align-content: center;
  & .apf-drive-thumb, & .apf-drive-mod, & .apf-drive-size, & .apf-drive-check { display: none; }
  & .apf-drive-nm { padding: 0; gap: 10px; }
  & .apf-drive-ki { width: 20px; height: 20px; }
}

/* list layout: header and rows share the sheet's columns through subgrid */
.apf-drive[data-view="list"] {
  & .apf-drive-scroll { padding-top: 0; }
  & .apf-drive-sheet { display: grid; grid-template-columns: [name] minmax(0, 1fr) [owner] minmax(110px, 170px) [mod] minmax(96px, 128px) [size] 84px; }
  & .apf-drive-lhead, & .apf-drive-items, & .apf-drive-item { grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; }
  & .apf-drive-lhead {
    position: sticky; top: 0; z-index: 2; height: 38px; align-items: center; background: var(--apf-drive-bg);
    border-bottom: 1px solid var(--apf-drive-line); font-size: 11.5px; font-weight: 600; color: var(--apf-drive-mute);
    & > * { padding: 0 12px; text-align: left; display: flex; align-items: center; gap: 5px; height: 100%; }
    & > :last-child { justify-content: flex-end; }
    & button:hover { color: var(--apf-drive-ink); }
    & [aria-pressed="true"] { color: var(--apf-drive-ink); }
  }
  & .apf-drive-items { gap: 0; }
  & .apf-drive-sec { display: none; }
  & .apf-drive-item {
    grid-template-areas: none; min-height: 40px; align-items: center; padding: 0; border-radius: 8px; border: 0;
    background: transparent; box-shadow: none;
    & > * { padding: 0 12px; }
    &::after { content: ""; position: absolute; left: 12px; right: 12px; bottom: 0; height: 1px; background: var(--apf-drive-line); }
    &:hover { background: var(--apf-drive-hover); }
    &[aria-selected="true"] { background: var(--apf-drive-tint); box-shadow: none; &::after { opacity: 0; } }
    &.is-drop { background: var(--apf-drive-tint2); scale: 1; box-shadow: inset 0 0 0 1.5px var(--apf-drive-accent); }
  }
  & .apf-drive-thumb, & .apf-drive-check { display: none; }
  & .apf-drive-nm, & .apf-drive-own, & .apf-drive-mod, & .apf-drive-size { grid-area: auto; }
  & .apf-drive-nm { gap: 10px; }
  & .apf-drive-item[data-kind="folder"] { padding: 0; min-height: 40px; & .apf-drive-nm { padding: 0 12px; } & .apf-drive-mod, & .apf-drive-size { display: block; } }
  & .apf-drive-own { display: flex; align-items: center; gap: 7px; font-size: 12.5px; color: var(--apf-drive-mute); min-width: 0; white-space: nowrap; overflow: hidden; }
  & .apf-drive-mod, & .apf-drive-size { font-size: 12.5px; padding-top: 0; }
  & .apf-drive-size { text-align: right; }
}
.apf-drive-av {
  width: 20px; height: 20px; border-radius: 50%; flex: none; display: grid; place-items: center;
  font: 650 8.5px/1 system-ui; letter-spacing: .02em; color: oklch(0.99 0 0); background: oklch(0.6 0.11 var(--h, 150));
}

.apf-drive-empty {
  display: none; place-items: center; text-align: center; padding: 60px 20px; color: var(--apf-drive-mute);
