.apf-drive[data-empty] .apf-drive-empty { display: grid; }
.apf-drive[data-empty] .apf-drive-lhead { display: none; }

.apf-drive-marquee {
  position: absolute; left: 0; top: 0; width: 0; height: 0; pointer-events: none; display: none; z-index: 3;
  border: 1px solid var(--apf-drive-accent); border-radius: 3px;
  background: color-mix(in oklch, var(--apf-drive-accent) 12%, transparent);
}
.apf-drive.is-marquee .apf-drive-marquee { display: block; }
.apf-drive.is-marquee .apf-drive-item { transition-duration: .06s; }

/* ── details pane ── */
.apf-drive-pane {
  grid-area: pane; min-height: 0; overflow: hidden; border-left: 1px solid var(--apf-drive-line); background: var(--apf-drive-bg);
  display: grid; grid-template-rows: auto minmax(0, 1fr);
  transition: visibility 0s .55s;
}
.apf-drive[data-pane="open"] .apf-drive-pane { visibility: visible; transition-delay: 0s; }
.apf-drive[data-pane="closed"] .apf-drive-pane { visibility: hidden; }
.apf-drive-panehead {
  display: flex; align-items: center; gap: 6px; padding: 12px 10px 4px 18px; min-width: var(--apf-drive-pw);
  & h3 { margin: 0; flex: 1; font-size: 10.5px; font-weight: 650; letter-spacing: .09em; text-transform: uppercase; color: var(--apf-drive-faint); }
}
.apf-drive-panebody {
  min-height: 0; overflow: auto; padding: 4px 18px 22px; min-width: var(--apf-drive-pw); scrollbar-width: thin;
  & > * { animation: apf-drive-in .45s var(--apf-drive-out) both; animation-delay: calc(var(--i, 0) * 45ms); }
}
.apf-drive-pv {
  position: relative; aspect-ratio: 4 / 3; border-radius: 12px; overflow: hidden; margin: 6px 0 14px;
  background: var(--apf-drive-panel); border: 1px solid var(--apf-drive-line);
  & > svg { width: 100%; height: 100%; display: block; stroke-width: 1; }
  &.is-stack { background: none; border: 0; overflow: visible; }
  & .apf-drive-stk {
    position: absolute; inset: 10% 14%; border-radius: 10px; overflow: hidden; border: 1px solid var(--apf-drive-line2);
    background: var(--apf-drive-raise); box-shadow: 0 10px 24px -14px color-mix(in oklch, var(--apf-drive-ink) 50%, transparent);
    rotate: calc((var(--j) - 1) * 5deg); translate: calc((var(--j) - 1) * 14px) calc(var(--j) * -3px);
    transition: rotate .5s var(--apf-drive-spring), translate .5s var(--apf-drive-spring);
    & svg { width: 100%; height: 100%; display: block; stroke-width: 1; }
  }
  &.is-folder { display: grid; place-items: center; background: var(--apf-drive-tint); & > svg { width: 42%; height: auto; color: var(--apf-drive-accent); stroke-width: 1.1; } }
}
.apf-drive-pvt {
  margin: 0 0 3px; font-size: clamp(15px, 1.45cqi, 17px); font-weight: 680; letter-spacing: -.015em; line-height: 1.25; text-wrap: balance; overflow-wrap: anywhere;
}
.apf-drive-pvs { margin: 0 0 14px; color: var(--apf-drive-mute); font-size: 12px; font-variant-numeric: tabular-nums; }
.apf-drive-acts {
  display: flex; gap: 6px; margin: 0 0 16px;
  & button {
    flex: 1; height: 32px; border-radius: 8px; border: 1px solid var(--apf-drive-line2); font-size: 12px; font-weight: 600;
    display: inline-flex; align-items: center; justify-content: center; gap: 6px; transition: background-color .15s;
    & svg { width: 15px; height: 15px; }
    &:hover { background: var(--apf-drive-hover); }
    &[aria-pressed="true"] svg { fill: oklch(0.78 0.15 80); color: oklch(0.66 0.15 70); }
  }
  & .apf-drive-primary { background: var(--apf-drive-ink); color: var(--apf-drive-bg); border-color: transparent; &:hover { background: color-mix(in oklch, var(--apf-drive-ink), var(--apf-drive-bg) 15%); } }
}
.apf-drive-dl {
  margin: 0 0 16px; display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 7px 14px; font-size: 12.5px;
  & dt { color: var(--apf-drive-mute); }
  & dd { margin: 0; text-align: right; font-variant-numeric: tabular-nums; overflow-wrap: anywhere; }
}
.apf-drive-h4 { margin: 18px 0 8px; font-size: 10.5px; font-weight: 650; letter-spacing: .09em; text-transform: uppercase; color: var(--apf-drive-faint); }
.apf-drive-hint { margin: 20px 0 0; padding-top: 14px; border-top: 1px dashed var(--apf-drive-line2); color: var(--apf-drive-mute); font-size: 12px; line-height: 1.5; text-wrap: pretty; }
.apf-drive-who {
  display: flex; align-items: center; gap: 10px; font-size: 12px; color: var(--apf-drive-mute);
  & .apf-drive-avs { display: flex; & .apf-drive-av { width: 26px; height: 26px; font-size: 9.5px; border: 2px solid var(--apf-drive-bg); margin-left: -7px; &:first-child { margin-left: 0; } } }
}
.apf-drive-feed {
  list-style: none; margin: 0; padding: 0; display: grid; gap: 10px;
  & li { display: grid; grid-template-columns: 20px minmax(0, 1fr); gap: 9px; font-size: 12px; line-height: 1.35; text-wrap: pretty; }
  & b { font-weight: 620; }
  & time { display: block; color: var(--apf-drive-faint); font-size: 11px; font-variant-numeric: tabular-nums; }
}
.apf-drive-types {
  display: grid; gap: 8px;
  & div { display: grid; grid-template-columns: 70px minmax(0, 1fr) 62px; align-items: center; gap: 10px; font-size: 12px; }
  & i { height: 6px; border-radius: 9px; background: var(--apf-drive-line); overflow: hidden; display: block; }
  & i::before { content: ""; display: block; height: 100%; width: var(--apf-drive-fill); background: var(--k); border-radius: inherit; animation: apf-drive-fillup .9s var(--apf-drive-out) both; }
  & span:last-child { text-align: right; color: var(--apf-drive-mute); font-variant-numeric: tabular-nums; }
}

/* ── status, toast, drag layer ── */
.apf-drive-status {
  grid-area: status; display: flex; justify-content: space-between; align-items: center; gap: 12px; padding: 7px 16px;
  border-top: 1px solid var(--apf-drive-line); font-size: 11.5px; color: var(--apf-drive-mute); white-space: nowrap; overflow: hidden;
  & [data-count] { font-variant-numeric: tabular-nums; }
  & .apf-drive-keys { display: flex; align-items: center; gap: 5px; overflow: hidden; }
  & .apf-drive-keys kbd:not(:first-child) { margin-left: 7px; }
  & .apf-drive-keys kbd + kbd, & .apf-drive-keys kbd + span { margin-left: 0; }
}
.apf-drive-layer { position: absolute; inset: 0; pointer-events: none; z-index: 40; overflow: clip; }
.apf-drive-ghost {
  position: absolute; left: 0; top: 0; width: 132px; will-change: translate;
  & .apf-drive-gc {
    position: absolute; inset: 0 auto auto 0; width: 132px; aspect-ratio: 16 / 11; border-radius: 10px; overflow: hidden;
    background: var(--apf-drive-raise); border: 1px solid var(--apf-drive-line2);
    box-shadow: 0 18px 30px -16px color-mix(in oklch, var(--apf-drive-ink) 60%, transparent);
    rotate: calc(var(--j) * 4deg - 3deg); translate: calc(var(--j) * 5px) calc(var(--j) * -3px);
    & svg { width: 100%; height: 100%; display: block; stroke-width: 1; }
    &.is-fold { display: grid; place-items: center; background: var(--apf-drive-tint); & svg { width: 44px; height: 44px; color: var(--apf-drive-accent); } }
  }
  & b {
    position: absolute; right: -10px; top: -10px; min-width: 24px; height: 24px; padding: 0 7px; border-radius: 99px; z-index: 4;
    display: grid; place-items: center; background: var(--apf-drive-accent); color: var(--apf-drive-bg); font: 700 12px/1 system-ui;
    font-variant-numeric: tabular-nums; animation: apf-drive-pulse .35s var(--apf-drive-spring);
  }
  & span {
    position: absolute; left: 0; top: calc(132px * 11 / 16 + 8px); white-space: nowrap; padding: 4px 9px; border-radius: 7px; z-index: 4;
    background: var(--apf-drive-ink); color: var(--apf-drive-bg); font-size: 11.5px; font-weight: 560;
    opacity: 0; translate: 0 -4px; transition: opacity .15s, translate .2s var(--apf-drive-out);
  }
  &.has-target span { opacity: 1; translate: 0 0; }
}
.apf-drive.is-dragging, .apf-drive.is-dragging * { cursor: grabbing !important; }
.apf-drive-toast {
  position: absolute; z-index: 50; left: 50%; bottom: 46px; translate: -50% 16px; max-width: calc(100% - 32px);
  display: flex; align-items: center; gap: 14px; padding: 9px 9px 9px 16px; border-radius: 11px;
  background: var(--apf-drive-ink); color: var(--apf-drive-bg); font-size: 12.5px;
  box-shadow: 0 16px 34px -14px color-mix(in oklch, var(--apf-drive-ink) 70%, transparent);
  opacity: 0; pointer-events: none; transition: translate .45s var(--apf-drive-spring), opacity .2s;
  & [data-msg] { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }
  & button { flex: none; padding: 5px 10px; border-radius: 7px; font-weight: 650; color: color-mix(in oklch, var(--apf-drive-accent), white 45%); &:hover { background: color-mix(in oklch, var(--apf-drive-bg) 12%, transparent); } }
  &.is-on { opacity: 1; translate: -50% 0; pointer-events: auto; }
  & :focus-visible { outline-color: var(--apf-drive-bg); }
}
.apf-drive-scrim {
  position: absolute; inset: 0; z-index: 20; background: color-mix(in oklch, var(--apf-drive-ink) 28%, transparent);
  opacity: 0; pointer-events: none; transition: opacity .3s;
}

/* ── medium: details become a drawer ── */
@container (width < 960px) {
  .apf-drive-app, .apf-drive[data-pane="closed"] .apf-drive-app { grid-template-columns: 200px minmax(0, 1fr) 0px; }
  .apf-drive-pane {
    position: absolute; z-index: 30; top: 0; right: 0; bottom: 0; width: min(var(--apf-drive-pw), 88cqi);
    translate: 100% 0; visibility: hidden; border-radius: 0 14px 14px 0;
    box-shadow: -24px 0 48px -24px color-mix(in oklch, var(--apf-drive-ink) 45%, transparent);
    transition: translate .5s var(--apf-drive-spring), visibility 0s .5s;
  }
  .apf-drive-panehead, .apf-drive-panebody { min-width: 0; }
  .apf-drive[data-pane] .apf-drive-pane { visibility: hidden; }
  .apf-drive[data-drawer] .apf-drive-pane { translate: 0 0; visibility: visible; transition-delay: 0s; }
  .apf-drive[data-drawer] .apf-drive-scrim { opacity: 1; pointer-events: auto; }
  .apf-drive-sort button { padding: 0 7px; }
  .apf-drive-status .apf-drive-keys { display: none; }
  .apf-drive-search { width: clamp(140px, 20cqi, 220px); }
  .apf-drive-crumbs button:not(:last-of-type), .apf-drive-crumbs svg { display: none; }
}

/* ── narrow: one pane at a time ── */
@container (width < 760px) {
  .apf-drive-app, .apf-drive[data-pane="closed"] .apf-drive-app {
    grid-template-columns: minmax(0, 1fr); grid-template-areas: "top" "main" "status";
  }
  .apf-drive-side {
    position: absolute; z-index: 30; top: 0; bottom: 0; left: 0; width: min(270px, 84cqi); border-radius: 14px 0 0 14px;
    translate: -102% 0; visibility: hidden; transition: translate .45s var(--apf-drive-spring), visibility 0s .45s;
    box-shadow: 24px 0 48px -24px color-mix(in oklch, var(--apf-drive-ink) 45%, transparent);
  }
  .apf-drive[data-nav] .apf-drive-side { translate: 0 0; visibility: visible; transition-delay: 0s; }
  .apf-drive[data-nav] .apf-drive-scrim { opacity: 1; pointer-events: auto; }
  .apf-drive-menu { display: grid; }
  .apf-drive-top { flex-wrap: wrap; gap: 8px; padding: 10px 12px 8px; }
  .apf-drive-crumbs { flex: 1 1 calc(100% - 44px); order: 0; & button:not(:last-of-type), & svg { display: none; } }
  .apf-drive-search { order: 2; flex: 1; width: auto; & kbd { display: none; } }
  .apf-drive-tools { order: 3; }
  .apf-drive-pane { inset: 0; width: auto; border-radius: 14px; box-shadow: none; translate: 24px 0; opacity: 0; transition: translate .4s var(--apf-drive-spring), opacity .25s, visibility 0s .4s; }
  .apf-drive[data-drawer] .apf-drive-pane { translate: 0 0; opacity: 1; }
  .apf-drive[data-drawer] .apf-drive-scrim { opacity: 0; }
  .apf-drive-back { display: grid; }
  .apf-drive-x { display: none; }
  .apf-drive-panehead { padding-left: 8px; }
  .apf-drive-scroll { padding: 10px 12px 20px; }
  .apf-drive-items { grid-template-columns: repeat(auto-fill, minmax(140px, 1fr)); gap: 10px; }
  .apf-drive[data-sel] .apf-drive-bulk { margin: 8px 12px 0; }
  .apf-drive-bulk .apf-drive-bulkbtns button { padding: 0 8px; & span, & kbd { display: none; } }
  .apf-drive[data-view="list"] .apf-drive-sheet { grid-template-columns: [name] minmax(0, 1fr) [mod] 88px [size] 70px; }
  .apf-drive[data-view="list"] .apf-drive-own, .apf-drive[data-view="list"] .apf-drive-lhead > span { display: none; }
  .apf-drive[data-view="list"] .apf-drive-item > *, .apf-drive[data-view="list"] .apf-drive-lhead > * { padding: 0 8px; }
}
@container (width < 560px) {
  .apf-drive-sort { display: none; }
  .apf-drive[data-view="list"] .apf-drive-sort { display: none; }
  .apf-drive[data-view="list"] .apf-drive-sheet { grid-template-columns: [name] minmax(0, 1fr) [size] 68px; }
  .apf-drive[data-view="list"] .apf-drive-mod, .apf-drive[data-view="list"] .apf-drive-lhead > [data-sort="mod"] { display: none; }
  .apf-drive-items { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .apf-drive-item[data-kind="folder"] { min-height: 44px; }
}

@media (prefers-reduced-motion: reduce) {
  .apf-drive *, .apf-drive *::before, .apf-drive *::after {
    animation-duration: .01ms !important; animation-delay: 0s !important; animation-iteration-count: 1 !important;
    transition-duration: .01ms !important; transition-delay: 0s !important;
  }
  .apf-drive-app { transition: none; }
  .apf-drive-item.is-drop { scale: 1; }
}

