@keyframes apf-upload-bob { 50% { translate: 0 -4px; } }

.apf-upload {
  /* re-theme with these four */
  --apf-upload-bg: oklch(0.185 0.008 105);
  --apf-upload-ink: oklch(0.95 0.012 105);
  --apf-upload-accent: oklch(0.89 0.185 122);
  --apf-upload-warn: oklch(0.72 0.17 42);

  --apf-upload-panel: color-mix(in oklch, var(--apf-upload-bg), white 3.5%);
  --apf-upload-raise: color-mix(in oklch, var(--apf-upload-bg), white 7%);
  --apf-upload-line: color-mix(in oklch, var(--apf-upload-ink) 10%, transparent);
  --apf-upload-line2: color-mix(in oklch, var(--apf-upload-ink) 17%, transparent);
  --apf-upload-mute: color-mix(in oklch, var(--apf-upload-ink) 58%, var(--apf-upload-bg));
  --apf-upload-faint: color-mix(in oklch, var(--apf-upload-ink) 34%, var(--apf-upload-bg));
  --apf-upload-tint: color-mix(in oklch, var(--apf-upload-accent) 12%, transparent);
  --apf-upload-on: oklch(0.2 0.03 122);
  --apf-upload-spring: linear(0, 0.06 3%, 0.24 7.5%, 0.53 13%, 0.82 19%, 0.97 25%, 1.04 30%, 1.05 35%, 1.03 42%, 1.005 52%, 0.998 64%, 1);
  --apf-upload-out: cubic-bezier(.2, .8, .2, 1);
  --apf-upload-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;

  position: relative; width: 100%; height: var(--apf-upload-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--apf-upload-bg); color: var(--apf-upload-ink);
  font: 13px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
  border-radius: 14px; color-scheme: dark; accent-color: var(--apf-upload-accent);
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :where(button, input) { font: inherit; color: inherit; }
  & :where(button) { cursor: pointer; background: none; border: 0; padding: 0; }
  & :where(svg) { fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & :focus-visible { outline: 2px solid var(--apf-upload-accent); outline-offset: 2px; }
  & kbd {
    font: 600 10px/1 var(--apf-upload-mono); padding: 3px 5px 2px; border-radius: 5px; white-space: nowrap;
    border: 1px solid var(--apf-upload-line2); border-bottom-width: 2px; color: var(--apf-upload-mute);
    background: color-mix(in oklch, var(--apf-upload-ink) 4%, transparent);
  }
  & h3 { margin: 0 0 10px; font-size: 10.5px; font-weight: 650; letter-spacing: .09em; text-transform: uppercase; color: var(--apf-upload-faint); }
  & .apf-upload-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
}

.apf-upload-app {
  height: 100%; display: grid;
  grid-template-columns: 284px minmax(0, 1fr);
  grid-template-rows: auto auto minmax(0, 1fr);
  grid-template-areas: "side head" "side sum" "side queue";
}

/* ── side ── */
.apf-upload-side {
  grid-area: side; min-height: 0; overflow-y: auto; scrollbar-width: thin;
  display: flex; flex-direction: column; gap: 22px; padding: 18px 18px 20px;
  background: var(--apf-upload-panel); border-right: 1px solid var(--apf-upload-line); border-radius: 14px 0 0 14px;
}
.apf-upload-brand {
  display: flex; align-items: center; gap: 10px;
  & svg { width: 30px; height: 30px; padding: 6px; border-radius: 9px; background: var(--apf-upload-accent); color: var(--apf-upload-on); stroke-width: 2.2; flex: none; }
  & b { display: block; font-size: 15px; font-weight: 720; letter-spacing: -.02em; }
  & span { color: var(--apf-upload-mute); font-size: 12px; }
}
.apf-upload-drop {
  --apf-upload-dash: 0deg;
  position: relative; display: grid; justify-items: center; text-align: center; gap: 3px; padding: 22px 14px 18px; border-radius: 14px; cursor: pointer;
  background:
    linear-gradient(var(--apf-upload-panel), var(--apf-upload-panel)) padding-box,
    repeating-conic-gradient(from var(--apf-upload-dash), var(--apf-upload-line2) 0 6deg, transparent 6deg 12deg) border-box;
  border: 1.5px solid transparent;
  transition: background-color .2s, scale .35s var(--apf-upload-spring);
  & .apf-upload-dropart {
    width: 52px; height: 52px; display: grid; place-items: center; border-radius: 16px; margin-bottom: 8px;
    background: var(--apf-upload-tint); color: var(--apf-upload-accent);
    & svg { width: 34px; height: 34px; stroke-width: 2; }
  }
  & b { font-size: 14px; font-weight: 650; text-wrap: balance; }
  & > span { color: var(--apf-upload-mute); font-size: 12.5px; display: inline-flex; gap: 6px; align-items: center; }
  & u { color: var(--apf-upload-ink); text-decoration-color: var(--apf-upload-accent); text-underline-offset: 3px; text-decoration-thickness: 1.5px; }
  & small { margin-top: 6px; color: var(--apf-upload-faint); font-size: 11px; text-wrap: balance; }
  &:hover .apf-upload-dropart svg { animation: apf-upload-bob 1.2s var(--apf-upload-out) infinite; }
  &:has(:focus-visible) { outline: 2px solid var(--apf-upload-accent); outline-offset: 2px; }
}
.apf-upload.is-over .apf-upload-drop {
  scale: 1.02;
  background:
    linear-gradient(color-mix(in oklch, var(--apf-upload-accent) 9%, var(--apf-upload-panel)), color-mix(in oklch, var(--apf-upload-accent) 9%, var(--apf-upload-panel))) padding-box,
    repeating-conic-gradient(from var(--apf-upload-dash), var(--apf-upload-accent) 0 6deg, transparent 6deg 12deg) border-box;
  animation: apf-upload-march 6s linear infinite;
}
.apf-upload-dests {
  display: grid; gap: 2px;
  & button {
    display: grid; grid-template-columns: 18px minmax(0, 1fr) auto; align-items: center; gap: 9px; height: 34px; padding: 0 10px; border-radius: 9px; text-align: left;
    transition: background-color .15s;
    & svg { width: 17px; height: 17px; color: var(--apf-upload-mute); }
    & span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
    & small { font-size: 11px; color: var(--apf-upload-faint); font-variant-numeric: tabular-nums; }
    &:hover { background: color-mix(in oklch, var(--apf-upload-ink) 5%, transparent); }
    &[aria-checked="true"] { background: var(--apf-upload-tint); font-weight: 600; & svg { color: var(--apf-upload-accent); } & small { color: var(--apf-upload-accent); } }
  }
}
.apf-upload-field {
  display: grid; grid-template-columns: 1fr auto; align-items: center; gap: 8px 10px; margin-bottom: 16px; font-size: 12.5px;
  & output { font: 650 12px/1 var(--apf-upload-mono); color: var(--apf-upload-accent); }
  & input[type="range"] { grid-column: 1 / -1; width: 100%; margin: 0; height: 18px; }
  & .apf-upload-seg { grid-column: 1 / -1; }
}
.apf-upload-ticks {
  grid-column: 1 / -1; display: flex; justify-content: space-between; margin-top: -6px; padding: 0 3px;
  & i { font: 500 10px/1 var(--apf-upload-mono); font-style: normal; color: var(--apf-upload-faint); }
}
.apf-upload-seg {
  display: grid; grid-auto-flow: column; grid-auto-columns: 1fr; padding: 2px; gap: 2px; border-radius: 9px; background: color-mix(in oklch, var(--apf-upload-ink) 6%, transparent);
  & button { height: 28px; border-radius: 7px; font-size: 12px; color: var(--apf-upload-mute); white-space: nowrap; transition: background-color .15s, color .15s; }
  & button:hover { color: var(--apf-upload-ink); }
  & [aria-checked="true"] { background: var(--apf-upload-raise); color: var(--apf-upload-ink); font-weight: 600; box-shadow: 0 1px 0 color-mix(in oklch, var(--apf-upload-ink) 10%, transparent) inset; }
}
.apf-upload-switch {
  display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 12px; align-items: start; cursor: pointer; position: relative;
  & input { position: absolute; opacity: 0; width: 34px; height: 20px; margin: 0; cursor: pointer; }
  & .apf-upload-knob {
    width: 34px; height: 20px; border-radius: 99px; background: var(--apf-upload-line2); position: relative; transition: background-color .25s; margin-top: 1px;
    &::after { content: ""; position: absolute; left: 2px; top: 2px; width: 16px; height: 16px; border-radius: 50%; background: var(--apf-upload-ink); transition: translate .4s var(--apf-upload-spring); }
  }
  & input:checked + .apf-upload-knob { background: var(--apf-upload-warn); &::after { translate: 14px 0; } }
  & input:focus-visible + .apf-upload-knob { outline: 2px solid var(--apf-upload-accent); outline-offset: 2px; }
  & b { display: block; font-weight: 600; font-size: 12.5px; }
  & small { display: block; color: var(--apf-upload-mute); font-size: 11.5px; line-height: 1.35; text-wrap: pretty; }
}
.apf-upload-keys ul {
  list-style: none; margin: 0; padding: 0; display: grid; gap: 7px; font-size: 12px; color: var(--apf-upload-mute);
  & li { display: grid; grid-template-columns: 76px 1fr; align-items: center; }
  & li span { display: flex; gap: 3px; }
}

/* ── header ── */
.apf-upload-head {
  grid-area: head; display: flex; align-items: center; gap: 14px; padding: 16px 20px 6px; min-width: 0;
}
.apf-upload-tabs { display: none; }
.apf-upload-title {
  flex: 1; min-width: 0;
  & h2 { margin: 0; font-size: clamp(17px, 1.9cqi, 21px); font-weight: 720; letter-spacing: -.025em; text-wrap: balance; }
  & p { margin: 2px 0 0; font-size: 12.5px; color: var(--apf-upload-mute); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.apf-upload-hacts { display: flex; gap: 8px; flex: none; }
.apf-upload-btn {
  display: inline-flex; align-items: center; gap: 7px; height: 34px; padding: 0 12px; border-radius: 9px; font-size: 12.5px; font-weight: 600;
  border: 1px solid var(--apf-upload-line2); transition: background-color .15s, border-color .15s, opacity .2s;
  & svg { width: 16px; height: 16px; }
