  &:disabled { opacity: .4; cursor: default; }
  &.is-strong { background: var(--apf-upload-ink); color: var(--apf-upload-bg); border-color: transparent; & kbd { color: inherit; border-color: color-mix(in oklch, var(--apf-upload-bg) 30%, transparent); background: none; opacity: .7; } &:hover { background: color-mix(in oklch, var(--apf-upload-ink), var(--apf-upload-bg) 12%); } }
