/* ── summary ── */
.apf-upload-sum {
  grid-area: sum; margin: 10px 20px 4px; padding: 14px 16px; border-radius: 14px; min-width: 0;
  background: var(--apf-upload-panel); border: 1px solid var(--apf-upload-line);
  display: grid; grid-template-columns: 96px auto minmax(0, 1fr); align-items: center; gap: 18px;
