/* drag files from the desktop anywhere onto the component */
let depth = 0;
const hasFiles = e => e.dataTransfer && [...(e.dataTransfer.types || [])].includes('Files');
root.addEventListener('dragenter', e => { if (!hasFiles(e)) return; e.preventDefault(); depth++; root.classList.add('is-over'); });
root.addEventListener('dragover', e => { if (!hasFiles(e)) return; e.preventDefault(); e.dataTransfer.dropEffect = 'copy'; });
root.addEventListener('dragleave', e => { if (!hasFiles(e)) return; depth = Math.max(0, depth - 1); if (!depth) root.classList.remove('is-over'); });
root.addEventListener('drop', e => { if (!hasFiles(e)) return; e.preventDefault(); depth = 0; root.classList.remove('is-over'); addFiles(e.dataTransfer.files); });

/* pointer reorder of waiting rows by their grip */
let drag = null;
listEl.addEventListener('pointerdown', e => {
  const grip = e.target.closest('[data-grip]'); if (!grip || e.button !== 0) return;
