  const ph = doc.createElement('div'); ph.className = 'apf-upload-ph'; ph.style.setProperty('--h', r.height + 'px');
  const ghost = row.cloneNode(true); ghost.classList.add('apf-upload-ghost'); ghost.removeAttribute('data-id'); ghost.removeAttribute('tabindex'); ghost.setAttribute('aria-hidden', 'true');
  ghost.style.width = r.width + 'px'; ghost.style.top = (r.top - br.top) + 'px';
