listEl.addEventListener('pointermove', e => {
  if (!drag) return;
  const dy = e.clientY - drag.y0;
  drag.ghost.style.translate = '0 ' + dy + 'px';
  const sibs = [...drag.box.children].filter(n => n !== drag.ghost && n !== drag.ph && n.classList.contains('apf-upload-row'));
  const gy = drag.ghost.getBoundingClientRect(), mid = gy.top + gy.height / 2;
  let before = null;
  for (const s of sibs) { const r = s.getBoundingClientRect(); if (mid < r.top + r.height / 2) { before = s; break; } }
  if (drag.ph.nextSibling !== before) {
