    if (!RM.matches) sibs.forEach(s => { const d = pos.get(s) - s.getBoundingClientRect().top; if (d) s.animate([{ transform: 'translateY(' + d + 'px)' }, { transform: 'none' }], { duration: 300, easing: SPRING }); });
