  const slots = Q.map((q, i) => (q.state === 'wait' || q.state === 'paused') ? i : -1).filter(i => i >= 0);
  order.forEach((q, k) => { Q[slots[k]] = q; });
  pending = false; render(true); say(d.q.name + ' moved to position ' + (order.indexOf(d.q) + 1));
  d.row.focus({ preventScroll: true });
