@keyframes apf-share-in { from { opacity: 0; translate: 0 6px; } }
@keyframes apf-share-menu { from { opacity: 0; scale: .96; translate: 0 -4px; } }

.apf-share {
  /* re-theme with these four */
  --apf-share-bg: oklch(0.986 0.004 340);
  --apf-share-ink: oklch(0.25 0.025 330);
  --apf-share-accent: oklch(0.49 0.16 342);
  --apf-share-warn: oklch(0.6 0.17 40);

  --apf-share-panel: color-mix(in oklch, var(--apf-share-bg), var(--apf-share-ink) 3.5%);
  --apf-share-raise: color-mix(in oklch, var(--apf-share-bg), white 70%);
  --apf-share-line: color-mix(in oklch, var(--apf-share-ink) 10%, transparent);
  --apf-share-line2: color-mix(in oklch, var(--apf-share-ink) 18%, transparent);
  --apf-share-mute: color-mix(in oklch, var(--apf-share-ink) 60%, var(--apf-share-bg));
  --apf-share-faint: color-mix(in oklch, var(--apf-share-ink) 38%, var(--apf-share-bg));
  --apf-share-tint: color-mix(in oklch, var(--apf-share-accent) 10%, var(--apf-share-bg));
  --apf-share-tint2: color-mix(in oklch, var(--apf-share-accent) 20%, var(--apf-share-bg));
  --apf-share-hover: color-mix(in oklch, var(--apf-share-ink) 4.5%, transparent);
  --apf-share-spring: linear(0, 0.06 3%, 0.24 7.5%, 0.53 13%, 0.82 19%, 0.97 25%, 1.04 30%, 1.05 35%, 1.03 42%, 1.005 52%, 0.998 64%, 1);
  --apf-share-out: cubic-bezier(.2, .8, .2, 1);
  --apf-share-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;

  position: relative; width: 100%; height: var(--apf-share-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--apf-share-bg); color: var(--apf-share-ink);
  font: 13px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
  border-radius: 14px; color-scheme: light; accent-color: var(--apf-share-accent);
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :where(button, input) { font: inherit; color: inherit; }
  & :where(button) { cursor: pointer; background: none; border: 0; padding: 0; }
  & :where(svg) { fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & :focus-visible { outline: 2px solid var(--apf-share-accent); outline-offset: 2px; }
  & kbd {
    font: 600 10px/1 var(--apf-share-mono); padding: 3px 5px 2px; border-radius: 5px; white-space: nowrap;
    border: 1px solid var(--apf-share-line2); border-bottom-width: 2px; color: var(--apf-share-mute); background: var(--apf-share-raise);
  }
  & h3 { margin: 0; font-size: 10.5px; font-weight: 650; letter-spacing: .09em; text-transform: uppercase; color: var(--apf-share-faint); }
  & .apf-share-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
}

.apf-share-app {
  height: 100%; display: grid;
  grid-template-columns: 208px minmax(0, 1fr) minmax(360px, 38cqi);
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "top top top" "tree panel review";
}

/* ── top ── */
.apf-share-top {
  grid-area: top; display: flex; align-items: center; justify-content: space-between; gap: 12px;
  padding: 12px 18px; border-bottom: 1px solid var(--apf-share-line);
}
.apf-share-brand {
  display: flex; align-items: center; gap: 10px;
  & svg { width: 30px; height: 30px; padding: 5px; border-radius: 9px; background: var(--apf-share-accent); color: var(--apf-share-bg); stroke-width: 1.8; flex: none; }
  & b { display: block; font-size: 14px; font-weight: 700; letter-spacing: -.015em; }
  & span { font-size: 12px; color: var(--apf-share-mute); }
}
.apf-share-views {
  display: none; padding: 2px; gap: 2px; border-radius: 10px; background: var(--apf-share-panel);
  & button { height: 30px; padding: 0 12px; border-radius: 8px; font-size: 12.5px; color: var(--apf-share-mute); white-space: nowrap; transition: background-color .15s, color .15s; }
  & [aria-selected="true"] { background: var(--apf-share-raise); color: var(--apf-share-ink); font-weight: 650; box-shadow: 0 1px 2px color-mix(in oklch, var(--apf-share-ink) 14%, transparent); }
}

/* ── tree ── */
.apf-share-tree {
  grid-area: tree; min-height: 0; overflow-y: auto; padding: 16px 10px 16px 12px; background: var(--apf-share-panel);
  border-right: 1px solid var(--apf-share-line); border-bottom-left-radius: 14px; scrollbar-width: thin;
  & h3 { padding: 0 8px 8px; }
  & ul { list-style: none; margin: 0; padding: 0; display: grid; gap: 1px; }
}
.apf-share-ti {
  display: grid; grid-template-columns: 18px minmax(0, 1fr) auto; align-items: center; gap: 8px; min-height: 34px; padding: 0 8px 0 calc(8px + var(--d, 0) * 16px);
  border-radius: 8px; cursor: pointer; outline: none; transition: background-color .15s;
  & > svg { width: 17px; height: 17px; color: var(--k, var(--apf-share-mute)); }
  & .apf-share-tn { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & .apf-share-badges { display: flex; align-items: center; gap: 4px; color: var(--apf-share-faint); font: 600 10.5px/1 system-ui; font-variant-numeric: tabular-nums; }
  & .apf-share-badges svg { width: 13px; height: 13px; }
  & .apf-share-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--apf-share-warn); }
  &:hover { background: var(--apf-share-hover); }
  &[aria-selected="true"] { background: var(--apf-share-tint2); font-weight: 620; & .apf-share-badges { color: var(--apf-share-accent); } }
  &:focus-visible { outline: 2px solid var(--apf-share-accent); outline-offset: -2px; }
}
.apf-share [data-kind="folder"] { --k: var(--apf-share-accent); }
.apf-share [data-kind="pdf"] { --k: oklch(0.58 0.17 29); }
.apf-share [data-kind="sheet"] { --k: oklch(0.56 0.13 150); }
.apf-share [data-kind="doc"] { --k: oklch(0.55 0.14 262); }
.apf-share-treenote { margin: 16px 8px 0; padding-top: 12px; border-top: 1px dashed var(--apf-share-line2); font-size: 11.5px; line-height: 1.5; color: var(--apf-share-mute); text-wrap: pretty; & b { color: var(--apf-share-ink); font-weight: 600; } }

/* ── share panel ── */
.apf-share-panel { grid-area: panel; min-height: 0; min-width: 0; display: grid; grid-template-rows: minmax(0, 1fr) auto; position: relative; }
.apf-share-scroll { min-height: 0; overflow-y: auto; padding: 18px 22px 22px; scrollbar-width: thin; }
.apf-share-head {
  display: grid; grid-template-columns: 42px minmax(0, 1fr); gap: 2px 12px; align-items: center; margin-bottom: 16px;
  & .apf-share-hic { grid-row: span 2; width: 42px; height: 42px; border-radius: 12px; display: grid; place-items: center; background: color-mix(in oklch, var(--k) 12%, transparent); color: var(--k); & svg { width: 22px; height: 22px; } }
  & h2 { margin: 0; font-size: clamp(16px, 1.7cqi, 19px); font-weight: 700; letter-spacing: -.02em; line-height: 1.2; text-wrap: balance; overflow-wrap: anywhere; }
  & p { margin: 0; font-size: 12px; color: var(--apf-share-mute); }
  & .apf-share-lim { grid-column: 1 / -1; margin-top: 12px; }
}
.apf-share-switch {
  display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 2px 12px; align-items: center; padding: 10px 12px; border-radius: 10px;
  background: var(--apf-share-panel); cursor: pointer; position: relative;
  & input { position: absolute; opacity: 0; width: 34px; height: 20px; margin: 0; left: 12px; top: 12px; cursor: pointer; }
  & .apf-share-knob {
    grid-row: span 2; width: 34px; height: 20px; border-radius: 99px; background: var(--apf-share-line2); position: relative; transition: background-color .25s;
    &::after { content: ""; position: absolute; left: 2px; top: 2px; width: 16px; height: 16px; border-radius: 50%; background: white; box-shadow: 0 1px 2px oklch(0 0 0 / .25); transition: translate .4s var(--apf-share-spring); }
  }
  & input:checked + .apf-share-knob { background: var(--apf-share-accent); &::after { translate: 14px 0; } }
  & input:focus-visible + .apf-share-knob { outline: 2px solid var(--apf-share-accent); outline-offset: 2px; }
  & b { font-weight: 620; font-size: 12.5px; }
  & small { color: var(--apf-share-mute); font-size: 11.5px; line-height: 1.35; text-wrap: pretty; }
}

.apf-share-add { position: relative; margin-bottom: 20px; }
.apf-share-field {
  display: flex; flex-wrap: wrap; align-items: center; gap: 6px; min-height: 44px; padding: 6px 8px 6px 10px; border-radius: 11px;
  background: var(--apf-share-raise); border: 1px solid var(--apf-share-line2); transition: border-color .15s, box-shadow .2s;
  &:focus-within { border-color: var(--apf-share-accent); box-shadow: 0 0 0 3px color-mix(in oklch, var(--apf-share-accent) 16%, transparent); }
  & input { flex: 1; min-width: 120px; border: 0; outline: none; background: none; height: 30px; font-size: 13px; &:focus-visible { outline: none; } }
  & input::placeholder { color: var(--apf-share-faint); }
  &:has(.apf-share-chip) kbd, &:focus-within kbd { display: none; }
}
.apf-share-chips { display: contents; }
.apf-share-chip {
  display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 4px 0 3px; border-radius: 99px; font-size: 12.5px; font-weight: 560;
  background: var(--apf-share-tint2); animation: apf-share-in .3s var(--apf-share-out);
  & button { width: 20px; height: 20px; border-radius: 50%; display: grid; place-items: center; color: var(--apf-share-mute); &:hover { background: color-mix(in oklch, var(--apf-share-ink) 10%, transparent); color: var(--apf-share-ink); } }
  & button svg { width: 12px; height: 12px; stroke-width: 2.2; }
  & .apf-share-av { width: 22px; height: 22px; font-size: 8.5px; }
}
.apf-share-sugg {
  position: absolute; z-index: 20; left: 0; right: 0; top: 48px; max-height: 260px; overflow-y: auto; padding: 5px; border-radius: 12px;
  background: var(--apf-share-raise); border: 1px solid var(--apf-share-line2);
  box-shadow: 0 18px 40px -16px color-mix(in oklch, var(--apf-share-ink) 40%, transparent);
  display: none; animation: apf-share-menu .22s var(--apf-share-out);
  &.is-open { display: grid; }
}
.apf-share-opt {
  display: grid; grid-template-columns: 30px minmax(0, 1fr) auto; align-items: center; gap: 10px; padding: 6px 8px; border-radius: 8px; cursor: pointer;
  & b { font-weight: 600; display: block; }
  & mark { background: none; color: var(--apf-share-accent); font-weight: 700; }
  & small { color: var(--apf-share-mute); font-size: 11.5px; }
  & em { font-style: normal; font-size: 11px; color: var(--apf-share-faint); }
  &[aria-selected="true"] { background: var(--apf-share-tint); }
}
.apf-share-invite {
  display: none; align-items: center; gap: 10px; margin-top: 10px;
  & .apf-share-check { display: inline-flex; align-items: center; gap: 6px; font-size: 12.5px; color: var(--apf-share-mute); margin-right: auto; & input { margin: 0; width: 15px; height: 15px; } }
}
.apf-share-add:has(.apf-share-chip) .apf-share-invite { display: flex; animation: apf-share-in .3s var(--apf-share-out); }
.apf-share-rolebtn {
  display: inline-flex; align-items: center; gap: 4px; height: 30px; padding: 0 6px 0 10px; border-radius: 8px; font-size: 12.5px; white-space: nowrap; color: var(--apf-share-ink);
  transition: background-color .15s;
  & svg { width: 15px; height: 15px; color: var(--apf-share-mute); }
  &:hover, &[aria-expanded="true"] { background: var(--apf-share-hover); }
  &[disabled] { cursor: default; color: var(--apf-share-mute); &:hover { background: none; } }
}
.apf-share-primary {
  height: 32px; padding: 0 14px; border-radius: 9px; font-weight: 650; font-size: 12.5px; display: inline-flex; align-items: center; gap: 6px;
  background: var(--apf-share-accent); color: var(--apf-share-bg); transition: background-color .15s, translate .2s var(--apf-share-out);
  &:hover { background: color-mix(in oklch, var(--apf-share-accent), black 12%); }
  &:active { translate: 0 1px; }
  & kbd { background: none; color: inherit; border-color: color-mix(in oklch, var(--apf-share-bg) 35%, transparent); opacity: .8; padding: 2px 4px 1px; }
  & kbd + kbd { margin-left: -3px; }
}
.apf-share-ghostbtn { height: 32px; padding: 0 12px; border-radius: 9px; font-size: 12.5px; font-weight: 600; color: var(--apf-share-mute); &:hover { background: var(--apf-share-hover); color: var(--apf-share-ink); } }

.apf-share-h4 { margin: 0 0 6px; font-size: 12px; font-weight: 650; color: var(--apf-share-mute); }
.apf-share-people { list-style: none; margin: 0 0 22px; padding: 0; }
.apf-share-psec { margin: 12px 0 4px; font-size: 11px; color: var(--apf-share-faint); display: flex; align-items: center; gap: 6px; & svg { width: 13px; height: 13px; } &:first-child { margin-top: 0; } }
.apf-share-person {
  display: grid; grid-template-columns: 34px minmax(0, 1fr) auto; align-items: center; gap: 10px; padding: 6px 4px; border-radius: 10px;
  transition: background-color .15s;
  &:hover { background: var(--apf-share-hover); }
  & .apf-share-who { min-width: 0; & b { display: flex; align-items: center; gap: 6px; font-weight: 600; } & small { display: block; color: var(--apf-share-mute); font-size: 11.5px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; } }
  & .apf-share-tag { font: 650 9.5px/1 system-ui; letter-spacing: .04em; text-transform: uppercase; padding: 3px 5px; border-radius: 5px; background: var(--apf-share-panel); color: var(--apf-share-mute); }
  & .apf-share-tag.is-new { background: var(--apf-share-accent); color: var(--apf-share-bg); }
  & .apf-share-tag.is-chg { background: var(--apf-share-tint2); color: var(--apf-share-accent); }
  & .apf-share-tag.is-ext { background: color-mix(in oklch, var(--apf-share-warn) 14%, transparent); color: color-mix(in oklch, var(--apf-share-warn), black 25%); }
  &.is-gone { & .apf-share-who b, & .apf-share-who small { text-decoration: line-through; color: var(--apf-share-faint); } & .apf-share-av { opacity: .4; } }
  &.is-enter { animation: apf-share-in .4s var(--apf-share-out) both; animation-delay: calc(var(--i, 0) * 40ms); }
}
.apf-share-av {
  width: 34px; height: 34px; border-radius: 50%; display: grid; place-items: center; flex: none;
  font: 650 11px/1 system-ui; letter-spacing: .02em; color: white; background: oklch(0.6 0.12 var(--h, 340));
  &.is-group { border-radius: 10px; background: color-mix(in oklch, var(--apf-share-ink) 8%, transparent); color: var(--apf-share-ink); & svg { width: 18px; height: 18px; } }
}

.apf-share-general {
  display: grid; grid-template-columns: 40px minmax(0, 1fr) auto; gap: 2px 12px; align-items: center; padding: 12px; border-radius: 12px; background: var(--apf-share-panel);
  & .apf-share-gic { grid-row: span 2; width: 40px; height: 40px; border-radius: 50%; display: grid; place-items: center; background: var(--apf-share-raise); color: var(--apf-share-mute); & svg { width: 19px; height: 19px; } }
  &[data-mode="org"] .apf-share-gic, &[data-mode="link"] .apf-share-gic { background: var(--apf-share-tint2); color: var(--apf-share-accent); }
  & .apf-share-gmode { justify-self: start; margin-left: -10px; font-weight: 620; font-size: 13px; }
  & small { grid-column: 2; color: var(--apf-share-mute); font-size: 12px; text-wrap: pretty; }
  & .apf-share-grole { grid-row: 1 / span 2; grid-column: 3; }
  & .apf-share-copy { grid-column: 1 / -1; justify-self: start; margin-top: 10px; display: inline-flex; align-items: center; gap: 7px; height: 32px; padding: 0 12px; border-radius: 9px; border: 1px solid var(--apf-share-line2); font-weight: 600; font-size: 12.5px; background: var(--apf-share-raise); & svg { width: 15px; height: 15px; } &:hover { border-color: var(--apf-share-accent); color: var(--apf-share-accent); } }
}

.apf-share-pending {
  display: flex; align-items: center; gap: 8px; padding: 10px 14px 10px 22px; border-top: 1px solid var(--apf-share-line);
  background: color-mix(in oklch, var(--apf-share-bg), var(--apf-share-accent) 4%);
  translate: 0 100%; opacity: 0; visibility: hidden; position: absolute; left: 0; right: 0; bottom: 0;
  transition: translate .45s var(--apf-share-spring), opacity .2s, visibility 0s .45s;
  & .apf-share-pn { margin-right: auto; font-weight: 600; font-size: 12.5px; display: inline-flex; align-items: center; gap: 8px; font-variant-numeric: tabular-nums; }
  & .apf-share-pn::before { content: ""; width: 8px; height: 8px; border-radius: 50%; background: var(--apf-share-accent); box-shadow: 0 0 0 4px var(--apf-share-tint2); }
}
.apf-share[data-dirty] .apf-share-pending { position: relative; translate: 0 0; opacity: 1; visibility: visible; transition-delay: 0s; }

/* ── review matrix ── */
.apf-share-review {
  grid-area: review; min-height: 0; min-width: 0; display: grid; grid-template-rows: auto minmax(0, 1fr) auto;
  border-left: 1px solid var(--apf-share-line); background: var(--apf-share-raise); border-bottom-right-radius: 14px;
}
.apf-share-rhead { padding: 16px 18px 6px; & p { margin: 6px 0 0; font-size: 12px; color: var(--apf-share-mute); text-wrap: pretty; & b { color: var(--apf-share-ink); font-weight: 650; } } }
.apf-share-mxwrap { position: relative; isolation: isolate; min-height: 0; overflow: auto; padding: 4px 14px 10px; scrollbar-width: thin; }
.apf-share-mx {
  border-collapse: separate; border-spacing: 3px; margin: 0 auto;
  & th { font-weight: 500; }
  & thead th { height: 100px; vertical-align: bottom; padding: 0 0 6px; cursor: pointer; }
  & thead th span {
    display: inline-block; writing-mode: vertical-rl; rotate: 180deg; max-height: 96px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
    font-size: 11px; color: var(--apf-share-mute); padding-left: 2px; transition: color .15s;
  }
  & thead th.is-col span { color: var(--apf-share-accent); font-weight: 680; }
  & thead th:hover span { color: var(--apf-share-ink); }
  & tbody th { text-align: left; padding: 0 8px 0 0; white-space: nowrap; }
  & .apf-share-rn { display: flex; align-items: center; gap: 7px; font-size: 12px; max-width: 118px; }
  & .apf-share-rn span { overflow: hidden; text-overflow: ellipsis; }
  & .apf-share-rn .apf-share-av { width: 20px; height: 20px; font-size: 8px; }
  & .apf-share-rn i { font: 700 8.5px/1 system-ui; font-style: normal; letter-spacing: .05em; color: var(--apf-share-warn); }
  & td { padding: 0; position: relative; }
  & td.is-col::before { content: ""; position: absolute; inset: -3px -1.5px; background: var(--apf-share-tint); z-index: -1; }
  & tr.is-row th .apf-share-rn span { color: var(--apf-share-accent); font-weight: 650; }
  & tbody tr:hover th .apf-share-rn span { color: var(--apf-share-accent); }
}
.apf-share-cell {
  --r: 0;
  width: 25px; height: 25px; border-radius: 7px; display: grid; place-items: center; outline: none; cursor: pointer; position: relative;
  font: 700 10.5px/1 var(--apf-share-mono); font-style: normal; color: var(--apf-share-faint);
  transition: background-color .3s, color .3s, box-shadow .3s, scale .3s var(--apf-share-spring);
  &[data-src="none"]::after { content: ""; width: 4px; height: 4px; border-radius: 50%; background: var(--apf-share-line2); }
  &[data-src="owner"] { background: var(--apf-share-ink); color: var(--apf-share-bg); font-family: system-ui, sans-serif; font-size: 10px; }
  &[data-src="direct"] { background: color-mix(in oklch, var(--apf-share-accent) calc(28% + var(--r) * 24%), var(--apf-share-bg)); color: var(--apf-share-bg); }
  &[data-src="direct"][data-r="1"] { color: var(--apf-share-accent); }
  &[data-src="group"] { background: color-mix(in oklch, var(--apf-share-accent) calc(28% + var(--r) * 24%), var(--apf-share-bg)); color: var(--apf-share-bg); box-shadow: inset 0 0 0 2px var(--apf-share-raise), inset 0 0 0 3.5px color-mix(in oklch, var(--apf-share-accent) 60%, var(--apf-share-bg)); }
  &[data-src="group"][data-r="1"] { color: var(--apf-share-accent); }
  &[data-src="inherit"] { background: color-mix(in oklch, var(--apf-share-accent) calc(6% + var(--r) * 6%), var(--apf-share-bg)); color: var(--apf-share-accent); }
  &[data-src="general"] { box-shadow: inset 0 0 0 1.5px color-mix(in oklch, var(--apf-share-accent) 45%, transparent); color: var(--apf-share-accent); background: repeating-linear-gradient(-45deg, transparent 0 3px, color-mix(in oklch, var(--apf-share-accent) 9%, transparent) 3px 4.5px); }
  &.is-diff::before {
    content: ""; position: absolute; inset: -3px; border-radius: 9px; border: 1.5px dashed var(--apf-share-warn); pointer-events: none;
  }
  &.is-diff::after { content: ""; position: absolute; right: -3px; top: -3px; width: 7px; height: 7px; border-radius: 50%; background: var(--apf-share-warn); border: 1.5px solid var(--apf-share-raise); }
  &:hover { filter: brightness(1.04); scale: 1.08; }
  &:focus-visible { outline: 2px solid var(--apf-share-ink); outline-offset: 1px; }
}
.apf-share-legend {
  list-style: none; margin: 0; padding: 10px 16px 14px; display: flex; flex-wrap: wrap; gap: 6px 14px; border-top: 1px solid var(--apf-share-line);
  font-size: 11.5px; color: var(--apf-share-mute);
  & li { display: inline-flex; align-items: center; gap: 6px; }
  & .apf-share-cell { width: 18px; height: 18px; font-size: 9px; border-radius: 5px; cursor: default; --r: 2; &:hover { scale: 1; } }
  & .apf-share-cell.is-diff::before { inset: -2px; border-radius: 6px; }
  & .apf-share-cell.is-diff::after { display: none; }
}
.apf-share-tip {
  position: absolute; z-index: 10; left: 0; top: 0; width: max-content; max-width: 230px; padding: 8px 10px; border-radius: 9px;
  background: var(--apf-share-ink); color: var(--apf-share-bg); font-size: 11.5px; line-height: 1.4; pointer-events: none; text-wrap: pretty;
  opacity: 0; translate: 0 4px; transition: opacity .15s, translate .2s var(--apf-share-out);
  & b { font-weight: 650; }
  & em { font-style: normal; color: color-mix(in oklch, var(--apf-share-accent), white 55%); }
  &.is-on { opacity: 1; translate: 0 0; }
}

/* ── menu and toast ── */
.apf-share-menu {
  position: absolute; z-index: 60; min-width: 220px; max-width: 280px; padding: 5px; border-radius: 12px;
  background: var(--apf-share-raise); border: 1px solid var(--apf-share-line2);
  box-shadow: 0 20px 44px -18px color-mix(in oklch, var(--apf-share-ink) 45%, transparent);
  animation: apf-share-menu .2s var(--apf-share-out); transform-origin: top right;
  &[hidden] { display: none; }
  & [role="menuitemradio"], & [role="menuitem"] {
    display: grid; grid-template-columns: 18px minmax(0, 1fr); gap: 1px 8px; width: 100%; padding: 7px 10px 7px 8px; border-radius: 8px; text-align: left; outline: none;
    & svg { width: 15px; height: 15px; grid-row: span 2; align-self: start; margin-top: 1px; color: var(--apf-share-accent); visibility: hidden; }
    & small { grid-column: 2; color: var(--apf-share-mute); font-size: 11.5px; line-height: 1.35; text-wrap: pretty; }
    &[aria-checked="true"] { font-weight: 620; & svg { visibility: visible; } }
    &:hover, &:focus { background: var(--apf-share-tint); }
    &[aria-disabled="true"] { color: var(--apf-share-faint); cursor: default; &:hover, &:focus { background: var(--apf-share-hover); } }
  }
  & [data-danger] { color: oklch(0.52 0.19 28); }
  & hr { border: 0; border-top: 1px solid var(--apf-share-line); margin: 4px 6px; }
}
.apf-share-toast {
  position: absolute; z-index: 70; left: 50%; bottom: 16px; translate: -50% 16px; max-width: calc(100% - 32px); padding: 10px 16px; border-radius: 11px;
  background: var(--apf-share-ink); color: var(--apf-share-bg); font-size: 12.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  box-shadow: 0 16px 34px -14px color-mix(in oklch, var(--apf-share-ink) 70%, transparent);
  opacity: 0; pointer-events: none; transition: translate .45s var(--apf-share-spring), opacity .2s;
  &.is-on { opacity: 1; translate: -50% 0; }
}

/* ── medium: tree + share, review behind a tab ── */
@container (width < 960px) {
  .apf-share-app { grid-template-columns: 200px minmax(0, 1fr); grid-template-areas: "top top" "tree panel"; }
  .apf-share-views { display: flex; & [data-v="items"] { display: none; } }
  .apf-share-review { grid-area: tree / tree / panel / panel; border-left: 0; border-radius: 0 0 14px 14px; display: none; }
  .apf-share[data-view="review"] .apf-share-review { display: grid; }
  .apf-share[data-view="review"] .apf-share-tree, .apf-share[data-view="review"] .apf-share-panel { display: none; }
  .apf-share-treenote { display: none; }
}
/* ── narrow: one pane ── */
@container (width < 760px) {
  .apf-share-app { grid-template-columns: minmax(0, 1fr); grid-template-areas: "top" "panel"; }
  .apf-share-top { flex-wrap: wrap; padding: 10px 12px; }
  .apf-share-views { flex: 1 1 100%; & button { flex: 1; } & [data-v="items"] { display: block; } }
  .apf-share-tree { grid-area: panel; display: none; border-right: 0; border-radius: 0 0 14px 14px; }
  .apf-share-review { grid-area: panel; }
  .apf-share[data-view="items"] .apf-share-tree { display: block; }
  .apf-share[data-view="items"] .apf-share-panel { display: none; }
  .apf-share[data-view="items"] .apf-share-treenote { display: block; }
  .apf-share-scroll { padding: 14px 14px 18px; }
  .apf-share-pending { padding: 10px 12px; }
  .apf-share-rhead { padding: 12px 14px 4px; }
  .apf-share-mxwrap { padding: 4px 8px 8px; }
}
@container (width < 440px) {
  .apf-share-brand span { display: none; }
  .apf-share-views button { padding: 0 6px; font-size: 12px; }
  .apf-share-person { grid-template-columns: 30px minmax(0, 1fr) auto; gap: 8px; & .apf-share-av { width: 30px; height: 30px; } }
  .apf-share-general { grid-template-columns: 34px minmax(0, 1fr); & .apf-share-gic { width: 34px; height: 34px; } & .apf-share-grole { grid-row: auto; grid-column: 2; justify-self: start; margin-left: -10px; } }
  .apf-share-pending .apf-share-primary kbd { display: none; }
  .apf-share-cell { width: 23px; height: 23px; }
  .apf-share-mx .apf-share-rn { max-width: 96px; }
}

@media (prefers-reduced-motion: reduce) {
  .apf-share *, .apf-share *::before, .apf-share *::after {
    animation-duration: .01ms !important; animation-iteration-count: 1 !important; animation-delay: 0s !important;
    transition-duration: .01ms !important; transition-delay: 0s !important;
  }
  .apf-share-cell:hover { scale: 1; }
}

