/* Share dialog: effective access is derived from grants, groups, inheritance and link settings. */
const doc = root.ownerDocument;
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const SPRING = 'linear(0, 0.06 3%, 0.24 7.5%, 0.53 13%, 0.82 19%, 0.97 25%, 1.04 30%, 1.05 35%, 1.03 42%, 1.005 52%, 0.998 64%, 1)';
const $ = (s, el) => (el || root).querySelector(s);
const $$ = (s, el) => [...(el || root).querySelectorAll(s)];
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const MAC = /Mac|iP/.test(navigator.platform || navigator.userAgent);
const uid = 'apfs' + Math.random().toString(36).slice(2, 7);
$$('[data-mod]').forEach(k => { k.textContent = MAC ? '⌘' : 'Ctrl'; });
const clone = o => JSON.parse(JSON.stringify(o));

/* ── directory ────────────────────────────────────────────────────── */
const PEOPLE = [
  { id: 'ama', n: 'Ama Ofori', t: 'Chief Executive', h: 25 },
  { id: 'leon', n: 'Leon Barrett', t: 'Chief Financial Officer', h: 250 },
  { id: 'sofia', n: 'Sofia Marchetti', t: 'General Counsel', h: 300 },
  { id: 'jonas', n: 'Jonas Weber', t: 'Head of FP&A', h: 160 },
  { id: 'mei', n: 'Mei Tanaka', t: 'Financial Controller', h: 60 },
  { id: 'nadia', n: 'Nadia Saleh', t: 'Executive Assistant', h: 205 },
  { id: 'ravi', n: 'Ravi Menon', t: 'Director, Northfield Capital', h: 125, ext: 1 },
  { id: 'clara', n: 'Clara Hoffmann', t: 'Independent Director', h: 350, ext: 1 },
  { id: 'tom', n: 'Tom Achterberg', t: 'Observer, Ostrava Ventures', h: 90, ext: 1 }
];
const GROUPS = [
  { id: 'g-fin', n: 'Finance team', m: ['leon', 'jonas', 'mei'] },
  { id: 'g-board', n: 'Board of directors', m: ['ama', 'ravi', 'clara'] }
];
const OWNER = 'ama';
const ITEMS = [
  { id: 'root', parent: null, name: 'FY27 Board Pack', kind: 'folder' },
  { id: 'deck', parent: 'root', name: 'Board deck Q3.pdf', kind: 'pdf' },
  { id: 'ffin', parent: 'root', name: 'Financials', kind: 'folder' },
  { id: 'pl', parent: 'ffin', name: 'P&L Q3 FY27.xlsx', kind: 'sheet' },
  { id: 'cash', parent: 'ffin', name: 'Cash forecast FY27.xlsx', kind: 'sheet' },
  { id: 'legal', parent: 'root', name: 'Legal', kind: 'folder' },
  { id: 'term', parent: 'legal', name: 'Series C term sheet.pdf', kind: 'pdf' },
  { id: 'pool', parent: 'legal', name: 'Option pool memo.docx', kind: 'doc' },
  { id: 'mins', parent: 'root', name: 'Minutes, Sep 18.docx', kind: 'doc' }
];
const ROLE = ['None', 'Viewer', 'Commenter', 'Editor', 'Owner'];
const VERB = ['open', 'view', 'comment on', 'edit', 'own'];
const ROLEDESC = ['', 'Can open and download', 'Can view and add comments', 'Can edit, organize and share', ''];
const LETTER = ['', 'V', 'C', 'E', 'O'];
const item = id => ITEMS.find(i => i.id === id);
const who = id => PEOPLE.find(p => p.id === id) || GROUPS.find(g => g.id === id);
const isGroup = id => id.startsWith('g-');
const depth = id => { let d = 0; for (let x = item(id); x.parent; x = item(x.parent)) d++; return d; };
const ancestors = id => { const out = []; for (let x = item(item(id).parent); x; x = item(x.parent)) out.push(x); return out; };

let saved = {
  grants: { root: { 'g-board': 1, leon: 3, sofia: 3, nadia: 2 }, deck: { tom: 2 }, ffin: { 'g-fin': 3 }, legal: { sofia: 3, 'g-board': 2 }, pool: { leon: 1 }, mins: { nadia: 3 }, pl: {}, cash: {}, term: {} },
  gen: { root: { mode: 'restricted', role: 1 }, deck: { mode: 'org', role: 1 } },
  limited: { legal: true }
};
let draft = clone(saved);
const S = { sel: 'legal', view: 'share', chips: [], invite: 1, notify: new Set(), act: 0, focusCell: [0, 0], enter: true };
let undoStack = [];

/* ── effective access ─────────────────────────────────────────────── */
const PRI = { owner: 5, direct: 4, group: 3, inherit: 2, general: 1, none: 0 };
function genOf(st, id) {
  for (let x = item(id); x; x = item(x.parent)) {
    if (st.gen[x.id]) return Object.assign({ from: x.id }, st.gen[x.id]);
    if (st.limited[x.id]) return { mode: 'restricted', role: 1, from: x.id };
  }
  return { mode: 'restricted', role: 1, from: 'root' };
}
function effective(st) {
  const res = {};
  ITEMS.forEach(it => {
    const row = res[it.id] = {};
    const g = genOf(st, it.id);
    PEOPLE.forEach(p => {
      let best = { r: 0, src: 'none' };
      const take = c => { if (c.r > best.r || (c.r === best.r && c.r && PRI[c.src] > PRI[best.src])) best = c; };
      if (p.id === OWNER) take({ r: 4, src: 'owner' });
      const gr = st.grants[it.id] || {};
      if (gr[p.id]) take({ r: gr[p.id], src: 'direct', from: it.id });
      GROUPS.forEach(G => { if (G.m.includes(p.id) && gr[G.id]) take({ r: gr[G.id], src: 'group', via: G.id, from: it.id }); });
      if (it.parent && !st.limited[it.id]) {
        const pe = res[it.parent][p.id];
        if (pe.r && pe.src !== 'owner' && pe.src !== 'general') take({ r: pe.r, src: 'inherit', from: pe.from, via: pe.via });
      }
      if (g.mode === 'link' || (g.mode === 'org' && !p.ext)) take({ r: g.role, src: 'general', mode: g.mode, from: g.from });
      row[p.id] = best;
    });
  });
  return res;
}
function diffCount() {
  let n = 0;
  ITEMS.forEach(it => {
    const a = saved.grants[it.id] || {}, b = draft.grants[it.id] || {};
    new Set([...Object.keys(a), ...Object.keys(b)]).forEach(k => { if ((a[k] || 0) !== (b[k] || 0)) n++; });
    if (JSON.stringify(saved.gen[it.id] || null) !== JSON.stringify(draft.gen[it.id] || null)) n++;
    if (!!saved.limited[it.id] !== !!draft.limited[it.id]) n++;
  });
  return n;
}
const itemDirty = id => {
  const a = saved.grants[id] || {}, b = draft.grants[id] || {};
  return [...new Set([...Object.keys(a), ...Object.keys(b)])].some(k => (a[k] || 0) !== (b[k] || 0)) ||
    JSON.stringify(saved.gen[id] || null) !== JSON.stringify(draft.gen[id] || null) || !!saved.limited[id] !== !!draft.limited[id];
};

/* ── icons ────────────────────────────────────────────────────────── */
const IC = {
  folder: '<path d="M3.5 7v10.5A1.5 1.5 0 0 0 5 19h14a1.5 1.5 0 0 0 1.5-1.5V9A1.5 1.5 0 0 0 19 7.5h-7L10 5H5A1.5 1.5 0 0 0 3.5 6.5Z"/>',
  pdf: '<path d="M6 3.5h8l4 4v13H6Z"/><path d="M14 3.5v4h4"/><path d="M9 13h6M9 16.5h4"/>',
  sheet: '<rect x="4" y="4" width="16" height="16" rx="2"/><path d="M4 9.5h16M4 14.5h16M10 9.5V20"/>',
  doc: '<path d="M6 3.5h8l4 4v13H6Z"/><path d="M9 11h6M9 14h6M9 17h3.5"/>',
  lock: '<rect x="5.5" y="10.5" width="13" height="9.5" rx="2"/><path d="M8.5 10.5V8a3.5 3.5 0 0 1 7 0v2.5"/>',
  org: '<path d="M4 20V6.5L11 4v16M11 9h9v11"/><path d="M7 8.5v.01M7 12v.01M7 15.5v.01M14.5 12.5h2M14.5 16h2"/>',
  link: '<path d="M10 14a4 4 0 0 0 5.7 0l2.8-2.8a4 4 0 0 0-5.7-5.7l-1 1"/><path d="M14 10a4 4 0 0 0-5.7 0l-2.8 2.8a4 4 0 0 0 5.7 5.7l1-1"/>',
  people: '<circle cx="9" cy="9" r="3"/><path d="M3.5 19c.5-3 2.7-4.6 5.5-4.6s5 1.6 5.5 4.6"/><path d="M15 6.2a3 3 0 0 1 0 5.6M17.5 14.6c1.6.6 2.6 2 3 4.4"/>',
  check: '<path d="m5.5 12.5 4 4 9-9"/>',
  x: '<path d="m7 7 10 10M17 7 7 17"/>',
  down: '<path d="m7 10 5 5 5-5"/>',
  up: '<path d="M12 19V6M6.5 11.5 12 6l5.5 5.5"/>',
  copy: '<rect x="8.5" y="8.5" width="11" height="11" rx="2"/><path d="M15.5 8.5V6a1.5 1.5 0 0 0-1.5-1.5H6A1.5 1.5 0 0 0 4.5 6v8A1.5 1.5 0 0 0 6 15.5h2.5"/>'
};
const svg = k => '<svg viewBox="0 0 24 24" aria-hidden="true">' + IC[k] + '</svg>';
const ini = n => n.split(' ').map(w => w[0]).slice(0, 2).join('');
const avatar = id => isGroup(id) ? '<span class="apf-share-av is-group" aria-hidden="true">' + svg('people') + '</span>' : '<span class="apf-share-av" style="--h:' + who(id).h + '" aria-hidden="true">' + ini(who(id).n) + '</span>';

