/* ── tooltip ──────────────────────────────────────────────────────── */
const tip = $('[data-tip]'), wrap = $('[data-mxwrap]');
function explain(cell) {
  const pid = cell.dataset.p, iid = cell.dataset.i, { e, s, diff } = cellInfo(pid, iid), p = who(pid), it = item(iid);
  let t = '<b>' + esc(p.n) + '</b> ';
  if (!e.r) t += 'can’t open <b>' + esc(it.name) + '</b>' + (draft.limited[iid] || ancestors(iid).some(a => draft.limited[a.id]) ? '. Legal has limited access.' : '.');
  else if (e.src === 'owner') t += 'owns everything in the pack.';
  else {
    t += 'can ' + VERB[e.r] + ' <b>' + esc(it.name) + '</b> ';
    t += e.src === 'direct' ? '— added directly.' : e.src === 'group' ? 'through <em>' + esc(who(e.via).n) + '</em>.' :
      e.src === 'inherit' ? '— inherited from <em>' + esc(item(e.from).name) + '</em>' + (e.via ? ' through ' + esc(who(e.via).n) : '') + '.' :
      'because ' + (e.mode === 'org' ? 'anyone at Halden' : 'anyone with the link') + ' can.';
