const hideTip = () => tip.classList.remove('is-on');
wrap.addEventListener('pointerover', e => { const c = e.target.closest('.apf-share-cell'); if (c) showTip(c); });
wrap.addEventListener('pointerleave', hideTip);
wrap.addEventListener('focusin', e => { const c = e.target.closest('.apf-share-cell'); if (c) showTip(c); });
wrap.addEventListener('focusout', hideTip);
function markRow(pid) { $$('[data-mx] tr').forEach(tr => tr.classList.toggle('is-row', !!pid && tr.dataset.r === String(PEOPLE.findIndex(p => p.id === pid)))); }

/* ── events ───────────────────────────────────────────────────────── */
let tt = 0;
function toast(msg) { const t = $('.apf-share-toast'); $('[data-msg]').textContent = msg; t.classList.add('is-on'); clearTimeout(tt); tt = setTimeout(() => { if (root.isConnected) t.classList.remove('is-on'); }, 3600); say(msg); }
function say(m) { const l = $('[data-live]'); l.textContent = ''; setTimeout(() => { if (root.isConnected) l.textContent = m; }, 30); }

root.addEventListener('click', e => {
  if (!e.target.closest('[data-menuel]') && !e.target.closest('[data-menu]')) closeMenu(false);
  const m = e.target.closest('[data-menu]');
  if (m && !m.disabled) { if (menuFor === m) closeMenu(true); else { closeMenu(false); openMenu(m); } return; }
  const un = e.target.closest('[data-unchip]'); if (un) { S.chips = S.chips.filter(x => x !== un.dataset.unchip); renderChips(); qIn.focus(); return; }
