root.addEventListener('change', e => {
  if (e.target.matches('[data-limited]')) { const it = item(S.sel), on = e.target.checked; change(d => { if (on) d.limited[it.id] = true; else delete d.limited[it.id]; }, 'Limited access ' + (on ? 'on' : 'off') + ' for ' + it.name); const sw = $('[data-limited]'); if (sw) sw.focus({ preventScroll: true }); }
});
$('[data-tree]').addEventListener('keydown', e => {
  const i = ITEMS.findIndex(x => x.id === S.sel);
  if (e.key === 'ArrowDown' || e.key === 'ArrowUp') { e.preventDefault(); const n = ITEMS[Math.max(0, Math.min(ITEMS.length - 1, i + (e.key === 'ArrowDown' ? 1 : -1)))]; select(n.id, true); }
  else if (e.key === 'Home' || e.key === 'End') { e.preventDefault(); select(ITEMS[e.key === 'Home' ? 0 : ITEMS.length - 1].id, true); }
  else if (e.key === 'ArrowLeft') { e.preventDefault(); const p = item(S.sel).parent; if (p) select(p, true); }
  else if (e.key === 'Enter' && root.clientWidth < 760) { S.view = 'share'; render(); }
});
$('[data-mx]').addEventListener('keydown', e => {
  let [r, c] = S.focusCell;
  const k = e.key;
  if (k === 'ArrowRight') c++; else if (k === 'ArrowLeft') c--; else if (k === 'ArrowDown') r++; else if (k === 'ArrowUp') r--;
