    const n = bs[(i + (k === 'ArrowRight' ? 1 : bs.length - 1)) % bs.length]; S.view = n.dataset.v; render(); $('.apf-share-views [data-v="' + S.view + '"]').focus();
  }
  if (e.target.closest && e.target.closest('[data-menu]') && k === 'ArrowDown') { e.preventDefault(); openMenu(e.target.closest('[data-menu]')); }
