css:
@property --apf-versions-sweep { syntax: '<percentage>'; inherits: false; initial-value: 100%; }
@keyframes apf-versions-ink { from { --apf-versions-sweep: 0%; } to { --apf-versions-sweep: 100%; } }
@keyframes apf-versions-thumb { from { translate: 0 0; } to { translate: 0 calc((1 / var(--vr, .3) - 1) * 100%); } }
@keyframes apf-versions-in { from { opacity: 0; translate: 0 8px; } }
@keyframes apf-versions-flash { 0%, 100% { box-shadow: 0 0 0 0 transparent; } 30% { box-shadow: 0 0 0 4px color-mix(in oklch, var(--apf-versions-accent) 30%, transparent); } }
@keyframes apf-versions-page { from { opacity: .35; filter: blur(1.5px); } }

.apf-versions {
  /* re-theme with these four */
  --apf-versions-bg: oklch(0.955 0.014 80);
  --apf-versions-paper: oklch(0.993 0.004 85);
  --apf-versions-ink: oklch(0.24 0.02 55);
  --apf-versions-accent: oklch(0.58 0.185 33);

  --apf-versions-line: color-mix(in oklch, var(--apf-versions-ink) 11%, transparent);
  --apf-versions-line2: color-mix(in oklch, var(--apf-versions-ink) 19%, transparent);
  --apf-versions-mute: color-mix(in oklch, var(--apf-versions-ink) 60%, var(--apf-versions-bg));
  --apf-versions-faint: color-mix(in oklch, var(--apf-versions-ink) 38%, var(--apf-versions-bg));
  --apf-versions-tint: color-mix(in oklch, var(--apf-versions-accent) 10%, var(--apf-versions-paper));
  --apf-versions-hover: color-mix(in oklch, var(--apf-versions-ink) 5%, transparent);
  --apf-versions-del: oklch(0.56 0.15 25);
  --apf-versions-spring: linear(0, 0.06 3%, 0.24 7.5%, 0.53 13%, 0.82 19%, 0.97 25%, 1.04 30%, 1.05 35%, 1.03 42%, 1.005 52%, 0.998 64%, 1);
  --apf-versions-out: cubic-bezier(.2, .8, .2, 1);
  --apf-versions-serif: ui-serif, "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif;
  --apf-versions-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;

  position: relative; width: 100%; height: var(--apf-versions-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--apf-versions-bg); color: var(--apf-versions-ink);
  font: 13px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
  border-radius: 14px; color-scheme: light; accent-color: var(--apf-versions-accent);
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :where(button, input) { font: inherit; color: inherit; }
  & :where(button) { cursor: pointer; background: none; border: 0; padding: 0; }
  & :where(svg) { fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  & :focus-visible { outline: 2px solid var(--apf-versions-accent); outline-offset: 2px; }
  & kbd {
    font: 600 10px/1 var(--apf-versions-mono); padding: 3px 5px 2px; border-radius: 5px; white-space: nowrap;
    border: 1px solid var(--apf-versions-line2); border-bottom-width: 2px; color: var(--apf-versions-mute); background: var(--apf-versions-paper);
  }
}

.apf-versions-app {
  height: 100%; display: grid;
  grid-template-columns: minmax(0, 1fr) 312px;
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "top side" "main side";
}

/* ── top ── */
.apf-versions-top {
  grid-area: top; display: flex; align-items: center; gap: 14px; padding: 14px 18px 12px 22px; min-width: 0;
  border-bottom: 1px solid var(--apf-versions-line);
}
.apf-versions-icon {
  width: 30px; height: 30px; border-radius: 8px; display: grid; place-items: center; color: var(--apf-versions-mute); flex: none;
  transition: background-color .15s, color .15s;
  & svg { width: 18px; height: 18px; }
  &:hover { background: var(--apf-versions-hover); color: var(--apf-versions-ink); }
  &:disabled { opacity: .35; cursor: default; &:hover { background: none; } }
}
.apf-versions-back { display: none; }
.apf-versions-doctitle {
  flex: 1; min-width: 0;
  & .apf-versions-kicker { font-size: 10.5px; font-weight: 650; letter-spacing: .1em; text-transform: uppercase; color: var(--apf-versions-accent); }
  & h2 { margin: 1px 0 0; font: 600 clamp(16px, 1.75cqi, 20px)/1.2 var(--apf-versions-serif); letter-spacing: -.01em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.apf-versions-tools { display: flex; align-items: center; gap: 14px; flex: none; }
.apf-versions-toggle {
  display: inline-flex; align-items: center; gap: 8px; font-size: 12.5px; cursor: pointer; white-space: nowrap; position: relative; user-select: none;
  & input { position: absolute; opacity: 0; width: 30px; height: 18px; margin: 0; cursor: pointer; }
  & > span { width: 30px; height: 18px; border-radius: 99px; background: var(--apf-versions-line2); position: relative; transition: background-color .25s; flex: none; }
  & > span::after { content: ""; position: absolute; left: 2px; top: 2px; width: 14px; height: 14px; border-radius: 50%; background: white; box-shadow: 0 1px 2px oklch(0 0 0 / .2); transition: translate .4s var(--apf-versions-spring); }
  & input:checked + span { background: var(--apf-versions-accent); }
  & input:checked + span::after { translate: 12px 0; }
  & input:focus-visible + span { outline: 2px solid var(--apf-versions-accent); outline-offset: 2px; }
  &.is-small { font-size: 12px; color: var(--apf-versions-mute); }
}
.apf-versions-nav {
  display: flex; align-items: center; gap: 2px; padding: 2px; border-radius: 10px; background: var(--apf-versions-paper); border: 1px solid var(--apf-versions-line);
  & [data-pos] { min-width: 64px; text-align: center; font: 600 11.5px/1 var(--apf-versions-mono); font-variant-numeric: tabular-nums; color: var(--apf-versions-mute); }
}

/* ── document ── */
.apf-versions-main { grid-area: main; min-height: 0; min-width: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); }
.apf-versions-banner {
  display: none; align-items: center; gap: 10px; margin: 12px 22px 0; padding: 9px 9px 9px 14px; border-radius: 11px; font-size: 12.5px;
  background: var(--apf-versions-ink); color: var(--apf-versions-paper); animation: apf-versions-in .35s var(--apf-versions-out);
  & span { flex: 1; min-width: 0; text-wrap: pretty; }
  & b { font-weight: 650; }
  & button { flex: none; height: 28px; padding: 0 11px; border-radius: 8px; font-weight: 650; font-size: 12px; background: color-mix(in oklch, var(--apf-versions-paper) 14%, transparent); &:hover { background: color-mix(in oklch, var(--apf-versions-paper) 22%, transparent); } }
  & .apf-versions-cta { background: var(--apf-versions-accent); color: white; &:hover { background: color-mix(in oklch, var(--apf-versions-accent), white 10%); } }
  & :focus-visible { outline-color: var(--apf-versions-paper); }
  &.is-on { display: flex; }
}
.apf-versions-stage { position: relative; min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) 16px; timeline-scope: --apf-versions-doc; }
.apf-versions-scroll {
  min-height: 0; overflow-y: auto; padding: 22px 18px 60px 22px; scrollbar-width: none; outline: none;
  scroll-timeline: --apf-versions-doc block; overscroll-behavior: contain;
  &::-webkit-scrollbar { display: none; }
}
.apf-versions-paper {
  max-width: 680px; margin: 0 auto; padding: clamp(28px, 5cqi, 56px) clamp(22px, 6cqi, 68px) 64px; border-radius: 4px;
  background: var(--apf-versions-paper); font: 15px/1.68 var(--apf-versions-serif); color: var(--apf-versions-ink);
  box-shadow: 0 1px 2px color-mix(in oklch, var(--apf-versions-ink) 10%, transparent), 0 24px 50px -30px color-mix(in oklch, var(--apf-versions-ink) 40%, transparent);
  font-variant-numeric: oldstyle-nums proportional-nums;
  &.is-swap { animation: apf-versions-page .45s var(--apf-versions-out); }
  & h1 { margin: 0; font-size: clamp(24px, 3cqi, 31px); line-height: 1.12; font-weight: 600; letter-spacing: -.015em; text-wrap: balance; }
  & .apf-versions-meta { margin: 10px 0 30px; padding-bottom: 18px; border-bottom: 1px solid var(--apf-versions-line); font: 500 11px/1.5 system-ui, sans-serif; letter-spacing: .1em; text-transform: uppercase; color: var(--apf-versions-mute); }
  & h3 { margin: 28px 0 8px; font: 650 12px/1.3 system-ui, sans-serif; letter-spacing: .08em; text-transform: uppercase; color: var(--apf-versions-ink); display: flex; gap: 10px; }
  & h3::before { content: counter(apfvsec, decimal-leading-zero); counter-increment: apfvsec; color: var(--apf-versions-accent); font-family: var(--apf-versions-mono); font-weight: 600; }
  & p { margin: 0 0 12px; text-wrap: pretty; hyphens: auto; }
  & .apf-versions-sign { margin-top: 30px; padding-top: 18px; border-top: 1px dashed var(--apf-versions-line2); font-style: italic; color: var(--apf-versions-mute); }
  counter-reset: apfvsec;
}
.apf-versions-table {
  display: grid; grid-template-columns: minmax(0, 1fr) auto auto auto; margin: 6px 0 16px; font: 13.5px/1.4 system-ui, sans-serif;
  font-variant-numeric: tabular-nums lining-nums;
  & .apf-versions-tr { display: grid; grid-column: 1 / -1; grid-template-columns: subgrid; border-bottom: 1px solid var(--apf-versions-line); }
  & .apf-versions-td { padding: 7px 0 7px 18px; text-align: right; white-space: nowrap; }
  & .apf-versions-td:first-child { padding-left: 0; text-align: left; white-space: normal; }
  & .is-head { font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--apf-versions-mute); }
  & .is-total { font-weight: 700; border-bottom: 0; border-top: 1.5px solid var(--apf-versions-ink); }
}

/* insertions sweep in like a highlighter; deletions are struck through as they arrive */
.apf-versions-paper ins, .apf-versions-paper del {
  --c: oklch(0.6 0.15 var(--a, 30));
  text-decoration: none; border-radius: 2px; padding: 0 1px; margin: 0 -1px; scroll-margin: 80px;
  animation: apf-versions-ink .7s var(--apf-versions-out) both; animation-delay: calc(min(var(--i, 0), 14) * 70ms + 120ms);
}
.apf-versions-paper ins {
  background: linear-gradient(color-mix(in oklch, var(--c) 22%, transparent), color-mix(in oklch, var(--c) 22%, transparent)) no-repeat 0 0 / var(--apf-versions-sweep) 100%;
  box-shadow: inset 0 -1.5px 0 var(--c);
}
.apf-versions-paper del {
  color: color-mix(in oklch, var(--apf-versions-del) 80%, var(--apf-versions-ink));
  background: linear-gradient(var(--apf-versions-del), var(--apf-versions-del)) no-repeat 0 55% / var(--apf-versions-sweep) 1.5px;
  opacity: .75;
}
.apf-versions-paper .is-cur { animation: apf-versions-flash 1.2s var(--apf-versions-out); border-radius: 3px; }
.apf-versions-paper .is-dim { opacity: .3; --c: oklch(0.6 0 0); }
.apf-versions-paper.no-changes ins { background: none; box-shadow: none; animation: none; }
.apf-versions-paper.no-changes del { display: none; }

/* change map with a viewport thumb driven by the scroller's own scroll timeline */
.apf-versions-rail {
  position: relative; margin: 22px 6px 22px 0; border-radius: 99px; background: var(--apf-versions-line);
  & i { position: absolute; left: 1px; right: 1px; height: 6px; border-radius: 2px; background: oklch(0.6 0.15 var(--a, 30)); cursor: pointer; translate: 0 -50%; transition: scale .25s var(--apf-versions-spring); }
  & i.is-del { background: var(--apf-versions-del); }
  & i:hover, & i.is-cur { scale: 1.6 1.4; }
}
.apf-versions-thumb {
  position: absolute; left: -2px; right: -2px; top: 0; height: calc(var(--vr, .3) * 100%); border-radius: 99px; pointer-events: none;
  border: 1.5px solid color-mix(in oklch, var(--apf-versions-ink) 45%, transparent); background: color-mix(in oklch, var(--apf-versions-ink) 6%, transparent);
}
@supports (animation-timeline: scroll()) {
  .apf-versions-thumb { animation: apf-versions-thumb linear both; animation-timeline: --apf-versions-doc; }
}

/* ── versions sidebar ── */
.apf-versions-side {
  grid-area: side; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr) auto auto;
  background: var(--apf-versions-paper); border-left: 1px solid var(--apf-versions-line); border-radius: 0 14px 14px 0;
}
.apf-versions-sidehead {
  display: flex; align-items: center; justify-content: space-between; padding: 16px 16px 10px 20px;
  & h3 { margin: 0; font-size: 10.5px; font-weight: 650; letter-spacing: .1em; text-transform: uppercase; color: var(--apf-versions-faint); }
}
.apf-versions-list { list-style: none; margin: 0; padding: 0 10px 16px; min-height: 0; overflow-y: auto; scrollbar-width: thin; outline: none; }
.apf-versions-day { padding: 14px 10px 6px; font-size: 11.5px; font-weight: 650; color: var(--apf-versions-mute); }
.apf-versions-v {
  --a: 30;
  position: relative; display: grid; grid-template-columns: 18px minmax(0, 1fr) auto; gap: 1px 10px; padding: 9px 10px 9px 8px; border-radius: 10px;
  cursor: pointer; outline: none; transition: background-color .15s;
