  { id: 'v7', who: 'kofi', t: '2026-10-01 10:02', ops: [['A 2% discount', 'A 1.5% discount']] },
  { id: 'v8', who: 'ines', t: '2026-10-02 09:15', name: 'Ready for signature', ops: [['Draft for discussion', 'Final for signature'], ['This agreement runs', 'This Agreement runs'], ['each shipment on arrival.', 'each shipment within two working days of arrival.'], ['written notice.', 'written notice.\n= Signed for Brightwater Ceramics Ltd. and for Oriel Home GmbH on the date of the last signature below.']] }
