let VERS = [];
{ let text = V1; STEPS.forEach(s => { (s.ops || []).forEach(([a, b]) => { text = text.replace(a, b); }); VERS.push({ id: s.id, who: s.who, t: s.t, name: s.name || '', text }); }); }
const TODAY = new Date(2026, 9, 2);

/* ── tokens and diff ──────────────────────────────────────────────── */
const tokCache = new Map();
function tokens(text) {
