  text.split('\n').forEach(line => {
    const m = /^(#|@|##|~h|~t|~|=) /.exec(line), type = m ? { '#': 'h1', '@': 'meta', '##': 'h3', '~h': 'rh', '~t': 'rt', '~': 'r', '=': 'sign' }[m[1]] : 'p';
