const pd = s => { const [d, t] = s.split(' '), [y, mo, dd] = d.split('-').map(Number), [h, mi] = t.split(':').map(Number); return new Date(y, mo - 1, dd, h, mi); };
const MON = 'Jan Feb Mar Apr May Jun Jul Aug Sep Oct Nov Dec'.split(' ');
