/* ── render the version list ──────────────────────────────────────── */
function renderList(newId) {
  const cur = VERS.length - 1, lo = S.base != null ? Math.min(S.base, S.sel) : -1, hi = S.base != null ? Math.max(S.base, S.sel) : -1;
  let h = '', lastDay = '';
  for (let k = cur; k >= 0; k--) {
    const v = VERS[k];
    if (S.named && !v.name && k !== cur && k !== S.sel && k !== S.base) continue;
    const day = dayLabel(v);
    if (day !== lastDay) { h += '<li class="apf-versions-day" role="presentation">' + day + '</li>'; lastDay = day; }
    const d = delta(k), a = AUTH[v.who].a;
    const tags = (k === cur ? '<span class="apf-versions-tag">Current</span>' : '') + (S.base === k ? '<span class="apf-versions-tag is-ghost">From</span>' : '') + (S.base != null && S.sel === k ? '<span class="apf-versions-tag is-ghost">To</span>' : '');
    h += '<li class="apf-versions-v' + (k === cur ? ' is-current' : '') + (k > lo && k < hi || (S.base != null && (k === lo || k === hi) && k !== lo) ? ' is-range' : '') + (S.base === k ? ' is-base' : '') + (v.id === newId ? ' is-new' : '') + '" role="option" data-k="' + k + '" style="--a:' + a + '" aria-selected="' + (k === S.sel) + '" tabindex="' + (k === S.sel ? 0 : -1) + '" aria-label="' + esc(label(v) + ' by ' + AUTH[v.who].n) + '">' +
      '<span class="apf-versions-dot"></span>' +
      '<span class="apf-versions-vt"><time>' + hm(pd(v.t)) + '</time>' + (v.name && S.renaming !== k ? '<b>' + esc(v.name) + '</b>' : '') + tags + '</span>' +
      (d ? '<span class="apf-versions-delta"><span class="p">+' + d[0] + '</span> <span class="m">−' + d[1] + '</span></span>' : '<span class="apf-versions-delta"></span>') +
      '<span class="apf-versions-who"><i></i>' + esc(AUTH[v.who].n) + (v.who === ME ? ' (you)' : '') + '</span>' +
      (S.renaming === k ? '<input class="apf-versions-rename" data-rename value="' + esc(v.name) + '" placeholder="Name this version" aria-label="Version name">' : '') +
      '<span class="apf-versions-vacts"><button type="button" class="apf-versions-cta" data-act="restore">Restore <kbd>R</kbd></button><button type="button" data-act="name">' + (v.name ? 'Rename' : 'Name') + ' <kbd>N</kbd></button></span></li>';
  }
  listEl.innerHTML = h;
  const ren = $('[data-rename]'); if (ren) { ren.focus({ preventScroll: true }); ren.select(); }
  const s = $('[aria-selected="true"]', listEl); if (s) revealIn(listEl, s);
  /* authors legend */
  $('[data-authors]').innerHTML = Object.keys(AUTH).map(k => '<button type="button" data-author="' + k + '" aria-pressed="' + !S.hidden.has(k) + '" style="--a:' + AUTH[k].a + '"><i></i>' + AUTH[k].n.split(' ')[0] + '</button>').join('');
}
function revealIn(box, el) {
