}
function renderBanner() {
  const cur = VERS.length - 1, v = VERS[S.sel];
  let h = '';
  if (S.base != null) {
    const a = Math.min(S.base, S.sel), b = Math.max(S.base, S.sel);
    h = '<span>Comparing <b>' + esc(label(VERS[a])) + '</b> with <b>' + esc(label(VERS[b])) + '</b> · ' + hunks.length + ' change' + (hunks.length === 1 ? '' : 's') + '</span><button type="button" data-act="exit">Exit compare <kbd style="background:none;color:inherit;border-color:currentColor;opacity:.7">Esc</kbd></button>';
  } else if (S.sel !== cur) {
    h = '<span>Viewing <b>' + esc(label(v)) + '</b> by ' + esc(AUTH[v.who].n) + '. Restoring adds it as a new version; nothing is lost.</span><button type="button" class="apf-versions-cta" data-act="restore">Restore this version</button>';
  }
  banner.innerHTML = h; banner.classList.toggle('is-on', !!h);
}
function render(o) {
  o = o || {};
  root.dataset.screen = S.screen;
  renderDoc(o.swap);
  renderList(o.newId);
  renderBanner();
}

/* ── actions ──────────────────────────────────────────────────────── */
let tt = 0;
function toast(msg, undo) {
  $('[data-msg]').textContent = msg;
  toastEl.querySelector('[data-act="undo"]').style.display = undo ? '' : 'none';
  toastEl.classList.add('is-on'); clearTimeout(tt);
  tt = setTimeout(() => { if (root.isConnected) toastEl.classList.remove('is-on'); }, 5000);
}
function select(k, extend) {
  k = Math.max(0, Math.min(VERS.length - 1, k));
  if (extend) { if (S.base == null) S.base = S.sel; if (k === S.base) return; }
  else S.base = null;
  S.sel = k; S.renaming = null;
  scroller.scrollTop = 0;
  render({ swap: true });
}
function restore() {
  const cur = VERS.length - 1; if (S.sel === cur && S.base == null) return;
  const src = VERS[S.sel], now = new Date(2026, 9, 2, 11, 20 + undoStack.filter(u => u.type === 'restore').length);
  const t = '2026-10-02 ' + hm(now);
  const v = { id: 'r' + Date.now().toString(36), who: ME, t, name: 'Restored “' + (src.name || stamp(src)) + '”', text: src.text };
  undoStack.push({ type: 'restore', sel: S.sel });
  VERS.push(v); S.base = null; S.sel = VERS.length - 1;
  render({ swap: true, newId: v.id });
  toast('Restored ' + label(src) + ' as a new version', 1);
}
function undo() {
  const u = undoStack.pop(); if (!u) { toast('Nothing to undo'); return; }
  if (u.type === 'restore') { VERS.pop(); S.sel = Math.min(u.sel, VERS.length - 1); S.base = null; render({ swap: true }); toast('Restore undone'); }
  else if (u.type === 'name') { VERS[u.k].name = u.prev; render(); toast('Name change undone'); }
}
function commitName(ok) {
  const k = S.renaming; if (k == null) return;
  const inp = $('[data-rename]'), val = inp ? inp.value.trim() : '';
  S.renaming = null;
  if (ok && val !== VERS[k].name) { undoStack.push({ type: 'name', k, prev: VERS[k].name }); VERS[k].name = val; toast(val ? 'Named “' + val + '”' : 'Name removed', 1); }
  renderList(); renderBanner();
  const s = $('[aria-selected="true"]', listEl); if (s) s.focus({ preventScroll: true });
}

root.addEventListener('click', e => {
  const a = e.target.closest('[data-act]');
  if (a) {
    const act = a.dataset.act;
    if (act === 'restore') { const li = a.closest('[data-k]'); if (li && +li.dataset.k !== S.sel) select(+li.dataset.k); restore(); }
    else if (act === 'name') { const li = a.closest('[data-k]'); S.renaming = li ? +li.dataset.k : S.sel; renderList(); }
    else if (act === 'exit') { S.base = null; render({ swap: true }); }
    else if (act === 'next') go(1);
    else if (act === 'prev') go(-1);
    else if (act === 'undo') undo();
    else if (act === 'list') { S.screen = 'list'; root.dataset.screen = 'list'; const s = $('[aria-selected="true"]', listEl); if (s) s.focus({ preventScroll: true }); }
    return;
  }
  const li = e.target.closest('.apf-versions-v');
  if (li && !e.target.closest('input')) {
    const k = +li.dataset.k;
    if (e.shiftKey && k !== S.sel) { if (S.base == null) S.base = S.sel; S.sel = k; if (S.base === S.sel) S.base = null; render({ swap: true }); }
    else if (k !== S.sel || S.base != null) select(k);
    if (root.clientWidth < 760) { S.screen = 'doc'; root.dataset.screen = 'doc'; }
    const s = $('[aria-selected="true"]', listEl); if (s) s.focus({ preventScroll: true });
    return;
  }
  const au = e.target.closest('[data-author]');
  if (au) { const k = au.dataset.author; if (S.hidden.has(k)) S.hidden.delete(k); else S.hidden.add(k); renderDoc(); renderList(); return; }
  const mark = e.target.closest('[data-rail] i');
  if (mark) { focusHunk(+mark.dataset.k); return; }
  if (e.target === rail) {
    const r = rail.getBoundingClientRect(), f = (e.clientY - r.top) / r.height;
    scroller.scrollTo({ top: f * scroller.scrollHeight - scroller.clientHeight / 2, behavior: RM.matches ? 'auto' : 'smooth' });
  }
});
root.addEventListener('change', e => {
  if (e.target.matches('[data-changes]')) { S.show = e.target.checked; renderDoc(); }
  else if (e.target.matches('[data-named]')) { S.named = e.target.checked; renderList(); }
});
root.addEventListener('focusout', e => { if (e.target.matches && e.target.matches('[data-rename]')) setTimeout(() => { if (root.isConnected && S.renaming != null && doc.activeElement !== $('[data-rename]')) commitName(true); }, 0); });
root.addEventListener('keydown', e => {
  const k = e.key, mod = e.metaKey || e.ctrlKey;
  if (e.target.matches && e.target.matches('[data-rename]')) {
