    return;
  }
  if (mod && k.toLowerCase() === 'z') { e.preventDefault(); undo(); return; }
  if (e.target.matches && e.target.matches('input')) { if (k === 'c' || k === 'C') { /* let the toggle handle it */ } return; }
  if (mod || e.altKey) return;
  const shown = $$('.apf-versions-v', listEl).map(li => +li.dataset.k);
  const i = shown.indexOf(S.sel);
  if (k === 'ArrowDown' || k === 'ArrowUp' || k === 'j' || k === 'k') {
    e.preventDefault();
    const n = shown[Math.max(0, Math.min(shown.length - 1, i + (k === 'ArrowDown' || k === 'j' ? 1 : -1)))];
    if (n == null || (n === S.sel && !e.shiftKey)) return;
    if (e.shiftKey) { if (S.base == null) S.base = S.sel; S.sel = n; if (S.base === S.sel) S.base = null; render({ swap: true }); }
    else select(n);
