  else if (k === '[') { e.preventDefault(); go(-1); }
  else if (k === 'c' || k === 'C') { const t = $('[data-changes]'); t.checked = !t.checked; S.show = t.checked; renderDoc(); }
  else if (k === 'r' || k === 'R') restore();
  else if (k === 'n' || k === 'N') { e.preventDefault(); S.renaming = S.sel; renderList(); }
  else if (k === 'Escape') { if (S.base != null) { S.base = null; render({ swap: true }); } else if (root.clientWidth < 760 && S.screen === 'doc') { S.screen = 'list'; root.dataset.screen = 'list'; } }
  else if (k === 'Enter' && listEl.contains(e.target) && root.clientWidth < 760) { S.screen = 'doc'; root.dataset.screen = 'doc'; }
});

const nativeThumb = CSS.supports('animation-timeline: scroll()');
if (!nativeThumb) scroller.addEventListener('scroll', syncThumb, { passive: true });
const ro = new ResizeObserver(() => { if (!root.isConnected) { ro.disconnect(); return; } renderRail(); });
