@keyframes apf-storage-in { from { opacity: 0; translate: 0 6px; } }
@keyframes apf-storage-drop { 0% { scale: 1; } 40% { scale: 1.12; } 100% { scale: 1; } }

.apf-storage {
  /* re-theme with these four */
  --apf-storage-bg: oklch(0.175 0.009 60);
  --apf-storage-ink: oklch(0.94 0.012 75);
  --apf-storage-accent: oklch(0.82 0.12 80);
  --apf-storage-warn: oklch(0.7 0.16 38);

  --apf-storage-panel: color-mix(in oklch, var(--apf-storage-bg), white 4%);
  --apf-storage-raise: color-mix(in oklch, var(--apf-storage-bg), white 8%);
  --apf-storage-line: color-mix(in oklch, var(--apf-storage-ink) 10%, transparent);
  --apf-storage-line2: color-mix(in oklch, var(--apf-storage-ink) 18%, transparent);
  --apf-storage-mute: color-mix(in oklch, var(--apf-storage-ink) 58%, var(--apf-storage-bg));
  --apf-storage-faint: color-mix(in oklch, var(--apf-storage-ink) 34%, var(--apf-storage-bg));
  --apf-storage-tint: color-mix(in oklch, var(--apf-storage-accent) 13%, transparent);
  --apf-storage-spring: linear(0, 0.06 3%, 0.24 7.5%, 0.53 13%, 0.82 19%, 0.97 25%, 1.04 30%, 1.05 35%, 1.03 42%, 1.005 52%, 0.998 64%, 1);
  --apf-storage-out: cubic-bezier(.2, .8, .2, 1);
  --apf-storage-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;

  position: relative; width: 100%; height: var(--apf-storage-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--apf-storage-bg); color: var(--apf-storage-ink);
  font: 13px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
  border-radius: 14px; color-scheme: dark; accent-color: var(--apf-storage-accent);
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :where(button, input) { font: inherit; color: inherit; }
  & :where(button) { cursor: pointer; background: none; border: 0; padding: 0; }
  & :where(svg) { fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & :focus-visible { outline: 2px solid var(--apf-storage-accent); outline-offset: 2px; }
  & kbd {
    font: 600 10px/1 var(--apf-storage-mono); padding: 3px 5px 2px; border-radius: 5px; white-space: nowrap;
    border: 1px solid var(--apf-storage-line2); border-bottom-width: 2px; color: var(--apf-storage-mute); background: color-mix(in oklch, var(--apf-storage-ink) 4%, transparent);
  }
  & h3 { margin: 0 0 10px; font-size: 10.5px; font-weight: 650; letter-spacing: .1em; text-transform: uppercase; color: var(--apf-storage-faint); }
  & .apf-storage-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
}

.apf-storage-app {
  height: 100%; display: grid;
  grid-template-columns: 250px minmax(0, 1fr) 318px;
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "side head right" "side chart right";
}

/* ── left ── */
.apf-storage-side {
  grid-area: side; min-height: 0; overflow-y: auto; scrollbar-width: thin; display: flex; flex-direction: column; gap: 24px; padding: 18px;
  background: var(--apf-storage-panel); border-right: 1px solid var(--apf-storage-line); border-radius: 14px 0 0 14px;
}
.apf-storage-brand {
  display: flex; align-items: center; gap: 10px;
  & svg { width: 30px; height: 30px; padding: 5px; border-radius: 9px; background: var(--apf-storage-accent); color: var(--apf-storage-bg); stroke-width: 2; flex: none; }
  & b { display: block; font-size: 14px; font-weight: 700; letter-spacing: -.015em; }
  & span { font-size: 12px; color: var(--apf-storage-mute); }
}
.apf-storage-big {
  margin: 0 0 12px; display: flex; align-items: baseline; gap: 8px; flex-wrap: wrap;
  & b { font-size: clamp(26px, 2.8cqi, 34px); font-weight: 720; letter-spacing: -.035em; font-variant-numeric: tabular-nums; }
  & span { color: var(--apf-storage-mute); font-size: 13px; }
}
.apf-storage-qbar {
  display: flex; height: 10px; border-radius: 99px; overflow: hidden; gap: 2px; background: color-mix(in oklch, var(--apf-storage-ink) 7%, transparent);
  & i { flex: 0 0 var(--w); background: var(--c); border-radius: 2px; transition: flex-basis .7s var(--apf-storage-spring); }
}
.apf-storage-qnote { margin: 10px 0 0; font-size: 12px; color: var(--apf-storage-mute); text-wrap: pretty; & b { color: var(--apf-storage-ink); font-weight: 600; font-variant-numeric: tabular-nums; } }
.apf-storage-seg {
  display: grid; grid-auto-flow: column; grid-auto-columns: auto; justify-content: start; padding: 2px; gap: 2px; border-radius: 10px; background: color-mix(in oklch, var(--apf-storage-ink) 6%, transparent); margin-bottom: 14px;
  & button { height: 28px; padding: 0 8px; border-radius: 8px; font-size: 12px; color: var(--apf-storage-mute); white-space: nowrap; display: inline-flex; align-items: center; gap: 5px; transition: background-color .15s, color .15s; }
  & button kbd { display: none; }
  & button:hover { color: var(--apf-storage-ink); }
  & [aria-checked="true"] { background: var(--apf-storage-raise); color: var(--apf-storage-ink); font-weight: 620; }
}
.apf-storage-key {
  list-style: none; margin: 0; padding: 0; display: grid; gap: 2px;
  & li { display: grid; grid-template-columns: 10px minmax(0, 1fr) auto; align-items: center; gap: 9px; padding: 5px 6px; border-radius: 7px; font-size: 12.5px; animation: apf-storage-in .4s var(--apf-storage-out) both; animation-delay: calc(var(--i) * 35ms); }
  & li > i { width: 10px; height: 10px; border-radius: 3px; background: var(--c); }
  & li span:last-child { font-variant-numeric: tabular-nums; color: var(--apf-storage-mute); font-size: 12px; }
  & li.is-on { background: color-mix(in oklch, var(--apf-storage-ink) 6%, transparent); }
}
.apf-storage-keys { margin: auto 0 0; font-size: 11px; color: var(--apf-storage-mute); line-height: 2.1; text-wrap: pretty; }

/* ── head ── */
.apf-storage-head { grid-area: head; display: flex; align-items: center; gap: 12px; padding: 14px 18px 4px; min-width: 0; }
.apf-storage-crumbs {
  display: flex; align-items: center; gap: 2px; min-width: 0; flex: 1; overflow: hidden;
  & button { padding: 4px 7px; border-radius: 7px; color: var(--apf-storage-mute); white-space: nowrap; font-size: 13px; &:hover { background: color-mix(in oklch, var(--apf-storage-ink) 6%, transparent); color: var(--apf-storage-ink); } }
  & button:last-of-type { color: var(--apf-storage-ink); font-weight: 700; font-size: clamp(15px, 1.6cqi, 18px); letter-spacing: -.02em; overflow: hidden; text-overflow: ellipsis; }
  & svg { width: 13px; height: 13px; color: var(--apf-storage-faint); flex: none; }
}
.apf-storage-tabs {
  display: none; padding: 2px; gap: 2px; border-radius: 10px; background: color-mix(in oklch, var(--apf-storage-ink) 6%, transparent);
  & button { height: 28px; padding: 0 10px; border-radius: 8px; font-size: 12.5px; color: var(--apf-storage-mute); white-space: nowrap; }
  & [aria-selected="true"] { background: var(--apf-storage-raise); color: var(--apf-storage-ink); font-weight: 620; }
  & [data-tabn]:not(:empty) { display: inline-grid; place-items: center; min-width: 18px; height: 18px; padding: 0 5px; margin-left: 4px; border-radius: 99px; background: var(--apf-storage-warn); color: var(--apf-storage-bg); font: 700 10.5px/1 system-ui; }
}

/* ── chart ── */
.apf-storage-chart { grid-area: chart; position: relative; min-height: 0; min-width: 0; display: grid; grid-template: minmax(0, 1fr) / minmax(0, 1fr); padding: 8px 12px 16px; }
.apf-storage-sb {
  width: 100%; height: 100%; display: block; overflow: visible; outline: none;
  & path { stroke: var(--apf-storage-bg); stroke-width: 1.25; cursor: pointer; outline: none; transition: opacity .25s, filter .25s, fill .45s var(--apf-storage-out); }
  & path.is-leaf { cursor: default; }
  & path:focus-visible { stroke: var(--apf-storage-ink); stroke-width: 2.5; }
  & path.is-queued { filter: saturate(.2) brightness(.7); }
  & .apf-storage-hatch { pointer-events: none; }
  &.is-hover path:not(.is-trail) { opacity: .38; }
  & .apf-storage-glow { fill: none; stroke: var(--apf-storage-line); stroke-width: 1; }
  & text { fill: oklch(0.2 0.02 60); stroke: none; font: 650 9.5px/1 system-ui, sans-serif; pointer-events: none; text-anchor: middle; dominant-baseline: middle; letter-spacing: .01em; }
}
.apf-storage-center {
  position: absolute; left: 50%; top: calc(50% - 4px); translate: -50% -50%; width: var(--d, 120px); aspect-ratio: 1; border-radius: 50%;
  display: grid; place-content: center; justify-items: center; text-align: center; gap: 2px; padding: 8px;
  transition: background-color .2s, scale .4s var(--apf-storage-spring);
  & .apf-storage-cname { font-size: 11.5px; color: var(--apf-storage-mute); max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; text-wrap: balance; }
  & b { font-size: clamp(16px, 2.1cqi, 24px); font-weight: 720; letter-spacing: -.03em; font-variant-numeric: tabular-nums; line-height: 1.05; }
  & .apf-storage-cpct { font: 600 10.5px/1.3 var(--apf-storage-mono); color: var(--apf-storage-accent); }
  &:hover { background: color-mix(in oklch, var(--apf-storage-ink) 5%, transparent); }
  &:active { scale: .96; }
  &[aria-disabled="true"] { cursor: default; &:hover { background: none; } }
}

/* ── right ── */
.apf-storage-right {
  grid-area: right; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr) auto;
  border-left: 1px solid var(--apf-storage-line); background: var(--apf-storage-panel); border-radius: 0 14px 14px 0;
}
.apf-storage-lhead { padding: 16px 16px 8px; & h3 { margin-bottom: 8px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; } }
.apf-storage-filters {
  display: flex; gap: 4px; flex-wrap: wrap;
  & button { height: 26px; padding: 0 9px; border-radius: 99px; font-size: 11.5px; color: var(--apf-storage-mute); border: 1px solid var(--apf-storage-line2); transition: background-color .15s, color .15s, border-color .15s; }
  & button:hover { color: var(--apf-storage-ink); }
  & [aria-checked="true"] { background: var(--apf-storage-ink); color: var(--apf-storage-bg); border-color: transparent; font-weight: 620; }
}
.apf-storage-list { list-style: none; margin: 0; padding: 4px 8px 10px; min-height: 0; overflow-y: auto; scrollbar-width: thin; outline: none; }
.apf-storage-row {
  display: grid; grid-template-columns: 30px minmax(0, 1fr) auto 28px; gap: 1px 10px; align-items: center; padding: 7px 8px; border-radius: 10px; cursor: default; outline: none;
  transition: background-color .15s, opacity .3s;
  &:hover, &.is-hot { background: color-mix(in oklch, var(--apf-storage-ink) 5%, transparent); }
