const sb = $('[data-sb]'), tip = $('[data-tip]'), listEl = $('[data-list]'), chart = $('.apf-storage-chart');

/* ── the tree (sizes in GB, last opened in days) ──────────────────── */
const QUOTA = 2000;
const RAW = ['Kestrel Labs', [
  ['Engineering', [
    ['Datasets', [['lidar-sweeps-q3.bag', 142, 'data', 12], ['lidar-sweeps-q2.bag', 128, 'data', 120], ['labels-v7.parquet', 9.4, 'data', 3]]],
    ['Build artifacts', [['nightly-2026-09.tar.zst', 84, 'archive', 40], ['nightly-2026-08.tar.zst', 81, 'archive', 70], ['release-4.2 symbols', 36, 'other', 210]]],
    ['Repository mirror', 22, 'code', 1]]],
  ['Field tests', [
    ['Drone flights', [['Flights, August', 158, 'video', 45], ['Flights, September', 132, 'video', 6]]],
    ['Telemetry logs', 18, 'data', 6]]],
  ['Marketing', [
    ['Campaign shoot', [['A-cam raw', 112, 'video', 25], ['B-cam raw', 58, 'video', 25], ['Stills selects', 16, 'image', 9]]],
    ['Launch film masters', 74, 'video', 90], ['Photo library', 41, 'image', 8], ['Decks', 2.6, 'doc', 2]]],
  ['Archive', [
    ['2024 projects', [['Client work 2024', 70, 'archive', 300], ['Internal 2024', 42, 'archive', 320]]],
    ['2023 projects', [['Client work 2023', 61, 'archive', 400], ['Internal 2023', 35, 'archive', 450]]],
    ['Old laptop backups', 54, 'archive', 500]]],
  ['Design', [
    ['Product renders', [['Hero shots', 38, 'image', 30], ['Exploded views', 26, 'image', 35]]],
    ['UI exports', 12, 'image', 5], ['Type & icon sources', 3.1, 'other', 60]]],
  ['Finance & ops', [['Contracts', 1.8, 'doc', 20], ['Invoices', 0.9, 'doc', 4], ['Payroll exports', 0.4, 'doc', 14]]]
]];
const HUE = { Engineering: 255, 'Field tests': 150, Marketing: 35, Archive: 78, Design: 340, 'Finance & ops': 195 };
const TYPES = { video: ['Video', 32], image: ['Images', 340], data: ['Datasets', 255], archive: ['Archives', 78], doc: ['Documents', 195], code: ['Code', 150], other: ['Other', null] };
const AGES = [[7, 'This week', 'oklch(0.76 0.1 150)'], [30, 'This month', 'oklch(0.8 0.11 112)'], [90, '1–3 months', 'oklch(0.82 0.12 82)'], [365, '3–12 months', 'oklch(0.72 0.15 52)'], [1e9, 'Over a year', 'oklch(0.63 0.17 28)']];
const nodes = [];
let nid = 0;
function build(r, parent, depth) {
  const n = { id: 'n' + (nid++), name: r[0], parent, depth, kids: null, size: 0, type: null, age: 0, deleted: false };
  nodes.push(n);
  if (Array.isArray(r[1])) n.kids = r[1].map(c => build(c, n, depth + 1));
