}
const ROOT = build(RAW, null, 0);
nodes.forEach(n => { let t = n; while (t.depth > 1) t = t.parent; n.top = t.depth === 1 ? t.name : null; });
const byId = id => nodes.find(n => n.id === id);
const gone = n => { for (let x = n; x; x = x.parent) if (x.deleted) return true; return false; };
const val = n => gone(n) ? 0 : n.kids ? n.kids.reduce((a, k) => a + val(k), 0) : n.size;
const leaves = n => n.kids ? n.kids.flatMap(leaves) : [n];
const under = (n, a) => { for (let x = n; x; x = x.parent) if (x === a) return true; return false; };
const ageOf = n => { const ls = leaves(n).filter(l => !gone(l)), t = ls.reduce((a, l) => a + l.size, 0); return t ? ls.reduce((a, l) => a + l.age * l.size, 0) / t : 0; };
const typeOf = n => { if (!n.kids) return n.type; const by = {}; leaves(n).filter(l => !gone(l)).forEach(l => { by[l.type] = (by[l.type] || 0) + l.size; }); return Object.keys(by).sort((a, b) => by[b] - by[a])[0] || 'other'; };
const pathOf = n => { const p = []; for (let x = n.parent; x && x.parent; x = x.parent) p.unshift(x.name); return p; };
function gb(v) { if (v >= 1000) return (v / 1000).toFixed(2) + ' TB'; if (v >= 100) return Math.round(v) + ' GB'; if (v >= 10) return v.toFixed(1) + ' GB'; if (v >= 1) return v.toFixed(1) + ' GB'; return Math.round(v * 1000) + ' MB'; }
const ago = d => d < 1 ? 'today' : d < 2 ? 'yesterday' : d < 14 ? Math.round(d) + ' days ago' : d < 60 ? Math.round(d / 7) + ' weeks ago' : d < 365 ? Math.round(d / 30) + ' months ago' : (d / 365).toFixed(1).replace('.0', '') + ' years ago';

/* ── state ────────────────────────────────────────────────────────── */
const S = { focus: ROOT, cursor: null, mode: 'folder', filter: 'all', tray: new Set(), tab: 'chart', hover: null };
const undoStack = [];

/* ── colours ──────────────────────────────────────────────────────── */
function colorOf(n) {
  if (S.mode === 'age') { const a = ageOf(n); return AGES.find(b => a <= b[0])[2]; }
  if (S.mode === 'type') {
    const t = typeOf(n), h = TYPES[t][1];
    if (h == null) return 'oklch(0.66 0.015 70)';
    return n.kids ? 'oklch(0.5 0.06 ' + h + ')' : 'oklch(0.72 0.12 ' + h + ')';
