  const L = [0, 0.74, 0.65, 0.57][Math.min(3, n.depth)] - (sib % 2) * 0.035;
  return 'oklch(' + L.toFixed(3) + ' ' + (n.depth === 1 ? 0.11 : 0.1) + ' ' + (h + (n.depth - 1) * 6) + ')';
}

/* ── partition and projection ─────────────────────────────────────── */
function partition() {
  const g = new Map();
  (function walk(n, a0, a1) {
    g.set(n, [a0, a1]);
    if (!n.kids) return;
    const tot = val(n); let a = a0;
    n.kids.slice().sort((x, y) => val(y) - val(x)).forEach(k => { const w = tot ? (a1 - a0) * val(k) / tot : 0; walk(k, a, a + w); a += w; });
  })(ROOT, 0, 1);
