}
function target() {
  const g = partition(), [f0, f1] = g.get(S.focus), span = f1 - f0 || 1, fd = S.focus.depth, T = new Map();
  nodes.forEach(n => {
    const [a0, a1] = g.get(n);
    const x0 = Math.max(0, Math.min(1, (a0 - f0) / span)) * Math.PI * 2, x1 = Math.max(0, Math.min(1, (a1 - f0) / span)) * Math.PI * 2;
