}
let cur = target(), anim = 0;
const R = y => 70 + (y - 1) * 42;
function arcPath(a0, a1, r0, r1) {
  const full = a1 - a0 > Math.PI * 2 - 1e-4;
  if (full) a1 = a0 + Math.PI * 2 - 1e-4;
  const p = (a, r) => (200 + r * Math.sin(a)).toFixed(2) + ' ' + (200 - r * Math.cos(a)).toFixed(2);
  const lg = a1 - a0 > Math.PI ? 1 : 0;
  return 'M' + p(a0, r1) + 'A' + r1 + ' ' + r1 + ' 0 ' + lg + ' 1 ' + p(a1, r1) + 'L' + p(a1, r0) + 'A' + r0 + ' ' + r0 + ' 0 ' + lg + ' 0 ' + p(a0, r0) + 'Z';
}
const paths = new Map();
let labelsG;
function setupSvg() {
