  const g = $('[data-arcs]', sb);
  nodes.forEach(n => {
    if (n === ROOT) return;
    const p = doc.createElementNS(NS, 'path');
    p.dataset.id = n.id; p.setAttribute('role', 'treeitem'); p.setAttribute('tabindex', '-1');
    if (!n.kids) p.classList.add('is-leaf');
