}
function draw(G, final) {
  const queued = n => [...S.tray].some(id => under(n, byId(id)));
  nodes.forEach(n => {
    const p = paths.get(n); if (!p) return;
    const c = G.get(n), w = c.x1 - c.x0;
    const vis = c.y >= 0.98 && c.y <= 3.02 && w > 0.0008 && val(n) > 0;
    if (!vis) { if (p.style.display !== 'none') p.style.display = 'none'; return; }
    p.style.display = '';
    const pad = w > 0.02 ? 0.003 : 0;
    p.setAttribute('d', arcPath(c.x0 + pad, c.x1 - pad, Math.max(0, R(c.y)) + 1, R(c.y + 1) - 1));
    if (final) {
      p.setAttribute('fill', colorOf(n));
      p.classList.toggle('is-queued', queued(n));
      p.setAttribute('aria-label', n.name + ', ' + gb(val(n)) + (n.kids ? ', folder' : ''));
      if (n.kids) p.setAttribute('aria-expanded', 'false'); else p.removeAttribute('aria-expanded');
