  if (!final) return;
  nodes.forEach(n => {
    const c = G.get(n); if (!c || c.y < 0.98 || c.y > 1.02 || !val(n)) return;
    const w = c.x1 - c.x0, rm = (R(1) + R(2)) / 2;
    if (w * rm < 64) return;
    const a = (c.x0 + c.x1) / 2, t = doc.createElementNS(NS, 'text');
    const x = 200 + rm * Math.sin(a), y = 200 - rm * Math.cos(a);
    let deg = a * 180 / Math.PI; if (deg > 90 && deg < 270) deg += 180;   /* tangent to the ring, never upside down */
    t.setAttribute('x', x.toFixed(1)); t.setAttribute('y', y.toFixed(1));
    t.setAttribute('transform', 'rotate(' + deg.toFixed(1) + ' ' + x.toFixed(1) + ' ' + y.toFixed(1) + ')');
    const max = Math.floor(w * rm / 6.2);
    t.textContent = n.name.length > max ? n.name.slice(0, max - 1) + '…' : n.name;
    labelsG.appendChild(t);
  });
}
const spring = t => t >= 1 ? 1 : 1 - Math.exp(-6.5 * t) * Math.cos(8.5 * t);
function transition() {
