}
function colorFill() { nodes.forEach(n => { const p = paths.get(n); if (p && !p.getAttribute('fill')) p.setAttribute('fill', colorOf(n)); }); }

/* ── chrome ───────────────────────────────────────────────────────── */
function render() {
  const ae = doc.activeElement, aeRow = root.contains(ae) && ae.closest && ae.closest('.apf-storage-row');
