  const byT = {}; leaves(ROOT).filter(l => !gone(l)).forEach(l => { byT[l.type] = (byT[l.type] || 0) + l.size; });
  $('[data-qbar]').innerHTML = Object.keys(byT).sort((a, b) => byT[b] - byT[a]).map(t => '<i style="--w:' + (byT[t] / QUOTA * 100).toFixed(2) + '%;--c:' + (TYPES[t][1] == null ? 'oklch(0.66 0.015 70)' : 'oklch(0.72 0.12 ' + TYPES[t][1] + ')') + '" title="' + TYPES[t][0] + ' ' + gb(byT[t]) + '"></i>').join('');
  const stale = leaves(ROOT).filter(l => !gone(l) && l.age > 90).reduce((a, l) => a + l.size, 0);
  $('[data-qnote]').innerHTML = '<b>' + gb(QUOTA - used) + '</b> free. Items not opened in 90 days hold <b>' + gb(stale) + '</b>.';
