css:
@keyframes apf-photos-rise { from { opacity: 0; translate: 0 18px; } }
@keyframes apf-photos-in { from { opacity: 0; translate: 0 6px; } }
@keyframes apf-photos-beat { 0% { scale: 1; } 35% { scale: 1.35; } 60% { scale: .92; } 100% { scale: 1; } }

.apf-photos {
  /* re-theme with these four */
  --apf-photos-bg: oklch(0.16 0.002 90);
  --apf-photos-ink: oklch(0.95 0.004 90);
  --apf-photos-accent: oklch(0.84 0.14 84);
  --apf-photos-warn: oklch(0.68 0.18 25);

  --apf-photos-panel: color-mix(in oklch, var(--apf-photos-bg), white 4%);
  --apf-photos-raise: color-mix(in oklch, var(--apf-photos-bg), white 9%);
  --apf-photos-line: color-mix(in oklch, var(--apf-photos-ink) 10%, transparent);
  --apf-photos-line2: color-mix(in oklch, var(--apf-photos-ink) 18%, transparent);
  --apf-photos-mute: color-mix(in oklch, var(--apf-photos-ink) 58%, var(--apf-photos-bg));
  --apf-photos-faint: color-mix(in oklch, var(--apf-photos-ink) 34%, var(--apf-photos-bg));
  --apf-photos-tint: color-mix(in oklch, var(--apf-photos-accent) 14%, transparent);
  --apf-photos-on: oklch(0.22 0.04 84);
  --apf-photos-spring: linear(0, 0.06 3%, 0.24 7.5%, 0.53 13%, 0.82 19%, 0.97 25%, 1.04 30%, 1.05 35%, 1.03 42%, 1.005 52%, 0.998 64%, 1);
  --apf-photos-out: cubic-bezier(.2, .8, .2, 1);
  --apf-photos-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;

  position: relative; width: 100%; height: var(--apf-photos-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--apf-photos-bg); color: var(--apf-photos-ink);
  font: 13px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
  border-radius: 14px; color-scheme: dark; accent-color: var(--apf-photos-accent);
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :where(button, input) { font: inherit; color: inherit; }
  & :where(button) { cursor: pointer; background: none; border: 0; padding: 0; }
  & :where(svg) { fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & :focus-visible { outline: 2px solid var(--apf-photos-accent); outline-offset: 2px; }
  & kbd {
    font: 600 10px/1 var(--apf-photos-mono); padding: 3px 5px 2px; border-radius: 5px; white-space: nowrap;
    border: 1px solid var(--apf-photos-line2); border-bottom-width: 2px; color: var(--apf-photos-mute); background: color-mix(in oklch, var(--apf-photos-ink) 4%, transparent);
  }
  & h3 { margin: 0; font-size: 10.5px; font-weight: 650; letter-spacing: .1em; text-transform: uppercase; color: var(--apf-photos-faint); }
  & .apf-photos-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
}

.apf-photos-app {
  height: 100%; display: grid;
  grid-template-columns: 226px minmax(0, 1fr);
  grid-template-rows: auto auto minmax(0, 1fr);
  grid-template-areas: "side top" "side bulk" "side main";
}

/* ── sidebar ── */
.apf-photos-side {
  grid-area: side; min-height: 0; overflow-y: auto; scrollbar-width: thin; padding: 16px 10px 16px 12px; display: flex; flex-direction: column; gap: 4px;
  background: var(--apf-photos-panel); border-right: 1px solid var(--apf-photos-line); border-radius: 14px 0 0 14px;
}
.apf-photos-brand {
  display: flex; align-items: center; gap: 10px; padding: 0 6px 14px;
  & svg { width: 30px; height: 30px; padding: 5px; border-radius: 50%; background: var(--apf-photos-accent); color: var(--apf-photos-on); stroke-width: 1.8; flex: none; }
  & b { display: block; font-size: 14px; font-weight: 700; letter-spacing: -.015em; }
  & span { font-size: 12px; color: var(--apf-photos-mute); }
}
.apf-photos-place, .apf-photos-album {
  display: grid; grid-template-columns: 28px minmax(0, 1fr) auto; align-items: center; gap: 10px; width: 100%; min-height: 36px; padding: 3px 8px 3px 6px; border-radius: 9px; text-align: left;
  transition: background-color .15s, outline-color .15s, scale .3s var(--apf-photos-spring);
  & svg { width: 18px; height: 18px; justify-self: center; color: var(--apf-photos-mute); }
  & span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
