/* Photo library: justified rows per day, FLIP on every re-layout, a lightbox that grows from its tile. */
const doc = root.ownerDocument;
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const SPRING = 'linear(0, 0.06 3%, 0.24 7.5%, 0.53 13%, 0.82 19%, 0.97 25%, 1.04 30%, 1.05 35%, 1.03 42%, 1.005 52%, 0.998 64%, 1)';
const OUT = 'cubic-bezier(.2,.8,.2,1)';
const $ = (s, el) => (el || root).querySelector(s);
const $$ = (s, el) => [...(el || root).querySelectorAll(s)];
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const uid = 'apfp' + Math.random().toString(36).slice(2, 7);

const scroller = $('[data-scroll]'), grid = $('[data-grid]'), lb = $('[data-lb]'), frame = $('[data-frame]'), stage = $('[data-stage]');
const scrub = $('[data-scrub]'), bubble = $('[data-bubble]'), layer = $('.apf-photos-layer'), toastEl = $('.apf-photos-toast');

/* ── seeded randomness ────────────────────────────────────────────── */
function hash(s) { let h = 2166136261; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; }
function rng(seed) { let s = hash(seed) || 1; const n = () => { s ^= s << 13; s ^= s >>> 17; s ^= s << 5; return (s >>> 0) / 4294967296; }; for (let i = 0; i < 5; i++) n(); return n; }

/* ── library ──────────────────────────────────────────────────────── */
const DAYS = [
  ['2026-10-01', 'Old Town', 'city city city city city', 19],
  ['2026-09-27', 'Saltmarsh', 'coast field coast coast field field coast', 7],
  ['2026-09-26', 'Larch Valley', 'forest forest lake forest forest lake forest lake', 9],
  ['2026-09-25', 'Larch Valley', 'mountain lake mountain mountain lake mountain', 8],
  ['2026-09-13', 'North Cape Trail', 'coast coast mountain coast mountain coast mountain coast mountain', 6],
  ['2026-09-12', 'North Cape Trail', 'mountain mountain aurora aurora aurora mountain aurora aurora', 15],
  ['2026-08-30', 'Dune Coast', 'dunes dunes coast dunes dunes dunes dunes', 7],
  ['2026-08-29', 'Dune Coast', 'dunes field dunes dunes field dunes', 8]
];
const ARS = [1.5, 1.5, 1.5, 4 / 3, 2 / 3, 3 / 4, 1, 16 / 9];
const PH = [];
let num = 4120;
DAYS.slice().reverse().forEach(([d, place, kinds, startH]) => {
  kinds.split(' ').forEach((kind, i) => {
    const id = 'p' + (num++), r = rng(id);
    const ar = kind === 'aurora' || kind === 'city' ? [1.5, 2 / 3, 1.5, 3 / 4][i % 4] : ARS[Math.floor(r() * ARS.length)];
    const mins = startH * 60 + i * (14 + Math.floor(r() * 40));
    PH.push({ id, n: num - 1, day: d, place, kind, ar, t: String(Math.floor(mins / 60) % 24).padStart(2, '0') + ':' + String(mins % 60).padStart(2, '0'), fav: false, deleted: false, mb: +(6.5 + r() * 7).toFixed(1), iso: [100, 200, 400, 800, 3200][Math.floor(r() * (kind === 'aurora' || kind === 'city' ? 2 : 5)) + (kind === 'aurora' || kind === 'city' ? 3 : 0)] });
  });
});
PH.reverse();
[2, 9, 15, 21, 28, 33, 40, 47].forEach(i => { if (PH[i]) PH[i].fav = true; });
const byDay = d => PH.filter(p => p.day === d);
const ALBUMS = [
  { id: 'cape', name: 'North Cape, Sep 2026', ids: PH.filter(p => p.place === 'North Cape Trail').map(p => p.id) },
  { id: 'larch', name: 'Autumn larches', ids: PH.filter(p => p.place === 'Larch Valley').map(p => p.id) },
  { id: 'night', name: 'Night sky', ids: PH.filter(p => p.kind === 'aurora' || p.kind === 'city').map(p => p.id) },
  { id: 'prints', name: 'Prints to order', ids: [PH[2].id, PH[15].id, PH[28].id, PH[40].id, PH[47].id] }
];
const byId = id => PH.find(p => p.id === id);
const S = { view: 'all', size: 168, sel: new Set(), anchor: null, focus: null, selmode: false, nav: false, lb: null, info: false };
const undoStack = [];

/* ── photographs, drawn ───────────────────────────────────────────── */
const artCache = new Map();
