  const inGrid = grid.contains(e.target) || e.target === root;
  if (!inGrid) return;
  if (k.startsWith('Arrow')) {
    e.preventDefault();
    const n = geo(S.focus || order[0], k); if (!n) return;
    if (e.shiftKey) { if (S.anchor == null) S.anchor = S.focus; selectRange(n, false); render(); }
    focusTile(n);
    return;
  }
  if (k === 'Enter') { e.preventDefault(); if (S.focus) openLb(S.focus); }
  else if (k === ' ') { e.preventDefault(); if (S.focus) { if (S.sel.has(S.focus)) S.sel.delete(S.focus); else S.sel.add(S.focus); S.anchor = S.focus; render(); } }
  else if (k.toLowerCase() === 'f' && !mod) favorite();
  else if (k === 'Delete' || k === 'Backspace') { e.preventDefault(); del(); }
});

/* ── resize: re-justify to the new width ──────────────────────────── */
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  if (grid.clientWidth && Math.abs(grid.clientWidth - lastW) > 0.5) layout(false);
  else renderScrub();
  if (root.clientWidth >= 760 && S.nav) { S.nav = false; render(); }
});
ro.observe(grid);
render();

