@property --apf-assets-sw { syntax: '<number>'; inherits: true; initial-value: 1.75; }
@keyframes apf-assets-in { from { opacity: 0; translate: 0 6px; } }
@keyframes apf-assets-pop { 0% { scale: .7; opacity: 0; } 60% { scale: 1.08; opacity: 1; } 100% { scale: 1; } }

.apf-assets {
  /* re-theme with these four */
  --apf-assets-bg: oklch(0.983 0.003 255);
  --apf-assets-ink: oklch(0.22 0.025 262);
  --apf-assets-accent: oklch(0.52 0.19 263);
  --apf-assets-warn: oklch(0.6 0.17 38);

  --apf-assets-paper: oklch(1 0 0);
  --apf-assets-panel: color-mix(in oklch, var(--apf-assets-bg), var(--apf-assets-ink) 3.5%);
  --apf-assets-line: color-mix(in oklch, var(--apf-assets-ink) 10%, transparent);
  --apf-assets-line2: color-mix(in oklch, var(--apf-assets-ink) 18%, transparent);
  --apf-assets-mute: color-mix(in oklch, var(--apf-assets-ink) 58%, var(--apf-assets-bg));
  --apf-assets-faint: color-mix(in oklch, var(--apf-assets-ink) 36%, var(--apf-assets-bg));
  --apf-assets-tint: color-mix(in oklch, var(--apf-assets-accent) 9%, var(--apf-assets-bg));
  --apf-assets-tint2: color-mix(in oklch, var(--apf-assets-accent) 17%, var(--apf-assets-bg));
  --apf-assets-hover: color-mix(in oklch, var(--apf-assets-ink) 4.5%, transparent);
  --apf-assets-draft: oklch(0.72 0.14 75);
  --apf-assets-spring: linear(0, 0.06 3%, 0.24 7.5%, 0.53 13%, 0.82 19%, 0.97 25%, 1.04 30%, 1.05 35%, 1.03 42%, 1.005 52%, 0.998 64%, 1);
  --apf-assets-out: cubic-bezier(.2, .8, .2, 1);
  --apf-assets-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --apf-assets-sz: 24px;
  --apf-assets-join: round;

  position: relative; width: 100%; height: var(--apf-assets-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--apf-assets-bg); color: var(--apf-assets-ink);
  font: 13px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
  border-radius: 14px; color-scheme: light; accent-color: var(--apf-assets-accent);
  -webkit-tap-highlight-color: transparent;
  transition: --apf-assets-sw .35s var(--apf-assets-out);

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :where(button, input) { font: inherit; color: inherit; }
  & :where(button) { cursor: pointer; background: none; border: 0; padding: 0; }
  & :where(svg) { fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & :focus-visible { outline: 2px solid var(--apf-assets-accent); outline-offset: 2px; }
  & kbd {
    font: 600 10px/1 var(--apf-assets-mono); padding: 3px 5px 2px; border-radius: 5px; white-space: nowrap;
    border: 1px solid var(--apf-assets-line2); border-bottom-width: 2px; color: var(--apf-assets-mute); background: var(--apf-assets-paper);
  }
  & h3 { margin: 0; font-size: 10.5px; font-weight: 650; letter-spacing: .1em; text-transform: uppercase; color: var(--apf-assets-faint); }
}

.apf-assets-app {
  height: 100%; display: grid;
  grid-template-columns: 206px minmax(0, 1fr) 316px;
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "side top insp" "side main insp";
}

/* ── side ── */
.apf-assets-side {
  grid-area: side; min-height: 0; overflow-y: auto; scrollbar-width: thin; padding: 16px 10px 16px 12px; display: flex; flex-direction: column; gap: 4px;
  background: var(--apf-assets-panel); border-right: 1px solid var(--apf-assets-line); border-radius: 14px 0 0 14px;
  & > h3 { padding: 14px 8px 4px; }
}
.apf-assets-brand {
  display: flex; align-items: center; gap: 10px; padding: 0 6px 4px;
  & svg { width: 30px; height: 30px; padding: 5px; border-radius: 9px; background: var(--apf-assets-ink); color: var(--apf-assets-bg); stroke-width: 1.8; flex: none; }
  & b { display: block; font-size: 14px; font-weight: 700; letter-spacing: -.015em; }
  & span { font-size: 12px; color: var(--apf-assets-mute); }
}
.apf-assets-cols, .apf-assets-stats { display: grid; gap: 1px; }
.apf-assets-col, .apf-assets-st {
  display: grid; grid-template-columns: 18px minmax(0, 1fr) auto; align-items: center; gap: 9px; height: 32px; padding: 0 9px; border-radius: 8px; text-align: left;
  transition: background-color .15s;
  & svg { width: 16px; height: 16px; color: var(--apf-assets-mute); }
  & small { font: 500 11px/1 system-ui; color: var(--apf-assets-faint); font-variant-numeric: tabular-nums; }
  &:hover { background: var(--apf-assets-hover); }
  &[aria-current="true"], &[aria-pressed="true"] { background: var(--apf-assets-tint2); font-weight: 620; & svg { color: var(--apf-assets-accent); } & small { color: var(--apf-assets-accent); } }
}
.apf-assets-st i { width: 9px; height: 9px; border-radius: 50%; justify-self: center; background: var(--c); }
.apf-assets-lib {
  margin: auto 0 0; padding: 14px 8px 0; border-top: 1px solid var(--apf-assets-line); display: grid; gap: 6px; font-size: 11.5px;
  & div { display: grid; gap: 1px; }
  & dt { color: var(--apf-assets-faint); font-size: 10.5px; text-transform: uppercase; letter-spacing: .08em; font-weight: 600; }
  & dd { margin: 0; color: var(--apf-assets-mute); }
}

/* ── top ── */
.apf-assets-top { grid-area: top; display: flex; align-items: center; gap: 14px; padding: 14px 16px 10px; min-width: 0; border-bottom: 1px solid var(--apf-assets-line); }
.apf-assets-search {
  flex: 1; min-width: 120px; display: flex; align-items: center; gap: 8px; height: 36px; padding: 0 8px 0 11px; border-radius: 10px;
  background: var(--apf-assets-paper); border: 1px solid var(--apf-assets-line2); transition: border-color .15s, box-shadow .2s;
  & svg { width: 16px; height: 16px; color: var(--apf-assets-mute); flex: none; }
  & input { flex: 1; min-width: 0; border: 0; outline: none; background: none; font-size: 13px; &:focus-visible { outline: none; } }
  & input::-webkit-search-cancel-button { display: none; }
  &:focus-within { border-color: var(--apf-assets-accent); box-shadow: 0 0 0 3px color-mix(in oklch, var(--apf-assets-accent) 15%, transparent); }
  &:has(input:not(:placeholder-shown)) kbd, &:focus-within kbd { display: none; }
}
.apf-assets-tune { display: flex; align-items: center; gap: 14px; flex: none; }
.apf-assets-knob {
  display: grid; gap: 2px; font-size: 11px; color: var(--apf-assets-mute); width: clamp(84px, 9cqi, 120px);
  & span { display: flex; justify-content: space-between; }
  & output { font: 650 11px/1 var(--apf-assets-mono); color: var(--apf-assets-ink); }
  & input { width: 100%; margin: 0; height: 16px; }
}
.apf-assets-seg {
  display: flex; padding: 2px; gap: 2px; border-radius: 9px; background: var(--apf-assets-panel);
  & button { width: 32px; height: 28px; border-radius: 7px; display: grid; place-items: center; color: var(--apf-assets-mute); transition: background-color .15s, color .15s; }
  & svg { width: 18px; height: 18px; }
  & [aria-checked="true"] { background: var(--apf-assets-paper); color: var(--apf-assets-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--apf-assets-ink) 15%, transparent); }
}

/* ── grid ── */
.apf-assets-main { grid-area: main; min-height: 0; min-width: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); }
.apf-assets-bar {
  display: flex; align-items: center; gap: 8px; padding: 10px 16px 0; font-size: 12px; color: var(--apf-assets-mute); min-height: 34px; flex-wrap: wrap;
  & b { color: var(--apf-assets-ink); font-weight: 650; font-variant-numeric: tabular-nums; }
  & .apf-assets-bulk { display: inline-flex; gap: 4px; margin-left: auto; animation: apf-assets-in .3s var(--apf-assets-out); }
  & .apf-assets-bulk button { height: 26px; padding: 0 9px; border-radius: 7px; border: 1px solid var(--apf-assets-line2); font-size: 12px; font-weight: 600; display: inline-flex; align-items: center; gap: 6px; background: var(--apf-assets-paper); &:hover { border-color: var(--apf-assets-ink); } & i { width: 8px; height: 8px; border-radius: 50%; background: var(--c); } }
}
.apf-assets-scroll { min-height: 0; overflow-y: auto; padding: 8px 16px 24px; scrollbar-width: thin; overscroll-behavior: contain; }
.apf-assets-grid {
  display: grid; gap: 6px; outline: none;
  grid-template-columns: repeat(auto-fill, minmax(calc(var(--apf-assets-sz) + 70px), 1fr));
}
.apf-assets-cell {
  position: relative; display: grid; grid-template-rows: 1fr auto; justify-items: center; align-items: center; gap: 8px; padding: 14px 6px 10px; border-radius: 12px;
  min-height: calc(var(--apf-assets-sz) + 62px); background: var(--apf-assets-paper); border: 1px solid var(--apf-assets-line); outline: none; cursor: default;
  transition: background-color .15s, border-color .15s, box-shadow .2s var(--apf-assets-out), opacity .2s;
  & .apf-assets-g {
    width: var(--apf-assets-sz); height: var(--apf-assets-sz); stroke-width: var(--apf-assets-sw); stroke-linejoin: var(--apf-assets-join); stroke-linecap: var(--apf-assets-cap, round);
    color: var(--apf-assets-ink); transition: width .35s var(--apf-assets-spring), height .35s var(--apf-assets-spring), translate .3s var(--apf-assets-spring);
  }
  & .apf-assets-cn { font: 500 11px/1.2 var(--apf-assets-mono); color: var(--apf-assets-mute); max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; padding: 0 2px; }
  & .apf-assets-cn mark { background: color-mix(in oklch, var(--apf-assets-accent) 16%, transparent); color: var(--apf-assets-accent); border-radius: 2px; font-weight: 700; }
  &:hover { border-color: var(--apf-assets-line2); box-shadow: 0 8px 18px -12px color-mix(in oklch, var(--apf-assets-ink) 35%, transparent); & .apf-assets-g { translate: 0 -2px; } }
  &[aria-selected="true"] { background: var(--apf-assets-tint); border-color: color-mix(in oklch, var(--apf-assets-accent) 60%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--apf-assets-accent) 60%, transparent); & .apf-assets-g { color: var(--apf-assets-accent); } & .apf-assets-cn { color: var(--apf-assets-accent); } }
  &.is-cur { box-shadow: inset 0 0 0 2px var(--apf-assets-accent); }
  &:focus-visible { outline: 2px solid var(--apf-assets-accent); outline-offset: 2px; }
  &[data-status="draft"]::after, &[data-status="deprecated"]::after {
    content: ""; position: absolute; right: 7px; top: 7px; width: 7px; height: 7px; border-radius: 50%; background: var(--apf-assets-draft);
  }
  &[data-status="deprecated"]::after { background: var(--apf-assets-warn); }
  &[data-status="deprecated"] .apf-assets-g { opacity: .4; }
  &[data-status="deprecated"] .apf-assets-cn { text-decoration: line-through; text-decoration-color: var(--apf-assets-warn); }
  &.is-enter { animation: apf-assets-pop .4s var(--apf-assets-out) both; animation-delay: calc(min(var(--i), 24) * 14ms); }
}
.apf-assets-none { display: none; padding: 50px 20px; text-align: center; color: var(--apf-assets-mute); text-wrap: pretty; & b { display: block; color: var(--apf-assets-ink); font-size: 15px; margin-bottom: 4px; } }
.apf-assets[data-none] .apf-assets-none { display: block; }

/* ── inspector ── */
.apf-assets-insp { grid-area: insp; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); border-left: 1px solid var(--apf-assets-line); background: var(--apf-assets-paper); border-radius: 0 14px 14px 0; }
.apf-assets-ihead { display: flex; align-items: center; gap: 8px; padding: 14px 16px 6px 18px; & h3 { flex: 1; } }
.apf-assets-chk { display: inline-flex; align-items: center; gap: 6px; font-size: 12px; color: var(--apf-assets-mute); cursor: pointer; & input { margin: 0; } }
.apf-assets-icon { width: 30px; height: 30px; border-radius: 8px; display: grid; place-items: center; color: var(--apf-assets-mute); & svg { width: 18px; height: 18px; } &:hover { background: var(--apf-assets-hover); color: var(--apf-assets-ink); } }
.apf-assets-back, .apf-assets-menu { display: none; }
.apf-assets-scrim { position: absolute; inset: 0; z-index: 20; background: color-mix(in oklch, var(--apf-assets-ink) 28%, transparent); opacity: 0; pointer-events: none; transition: opacity .3s; }
.apf-assets-ibody { min-height: 0; overflow-y: auto; padding: 4px 18px 20px; scrollbar-width: thin; & > * { animation: apf-assets-in .4s var(--apf-assets-out) both; animation-delay: calc(var(--i, 0) * 40ms); } }
.apf-assets-stage {
  --cell: calc(100% / 24);
  position: relative; aspect-ratio: 1; border-radius: 12px; overflow: hidden; margin: 6px 0 14px; background: var(--apf-assets-paper);
  border: 1px solid var(--apf-assets-line2);
  background-image:
    linear-gradient(to right, color-mix(in oklch, var(--apf-assets-ink) 7%, transparent) 1px, transparent 1px),
    linear-gradient(to bottom, color-mix(in oklch, var(--apf-assets-ink) 7%, transparent) 1px, transparent 1px);
  background-size: var(--cell) var(--cell);
  & svg { position: absolute; inset: 0; width: 100%; height: 100%; }
  & .apf-assets-kl { stroke: oklch(0.65 0.17 350); stroke-width: .06; fill: none; opacity: .75; transition: opacity .25s; }
  & .apf-assets-kl .apf-assets-pad { fill: color-mix(in oklch, oklch(0.65 0.17 350) 10%, transparent); stroke: none; }
  & .apf-assets-big { stroke-width: var(--apf-assets-sw); stroke-linejoin: var(--apf-assets-join); stroke-linecap: var(--apf-assets-cap, round); color: var(--apf-assets-ink); }
  & .apf-assets-nodes circle { fill: var(--apf-assets-paper); stroke: var(--apf-assets-accent); stroke-width: .08; }
}
.apf-assets[data-nokeylines] .apf-assets-kl { opacity: 0; }
.apf-assets-mini { display: flex; align-items: flex-end; gap: 14px; margin: -2px 0 14px; color: var(--apf-assets-ink); & svg { stroke-width: var(--apf-assets-sw); stroke-linejoin: var(--apf-assets-join); stroke-linecap: var(--apf-assets-cap, round); } & span { display: grid; justify-items: center; gap: 4px; font: 500 10px/1 var(--apf-assets-mono); color: var(--apf-assets-faint); } }
.apf-assets-name { margin: 0 0 2px; font: 680 clamp(16px, 1.6cqi, 19px)/1.2 var(--apf-assets-mono); letter-spacing: -.02em; overflow-wrap: anywhere; }
.apf-assets-meta { margin: 0 0 14px; font-size: 12px; color: var(--apf-assets-mute); font-variant-numeric: tabular-nums; }
.apf-assets-h4 { margin: 16px 0 7px; font-size: 10.5px; font-weight: 650; letter-spacing: .1em; text-transform: uppercase; color: var(--apf-assets-faint); }
.apf-assets-status {
  display: grid; grid-template-columns: repeat(3, 1fr); padding: 2px; gap: 2px; border-radius: 9px; background: var(--apf-assets-panel);
  & button { height: 28px; border-radius: 7px; font-size: 12px; color: var(--apf-assets-mute); display: inline-flex; align-items: center; justify-content: center; gap: 6px; transition: background-color .15s, color .15s; & i { width: 7px; height: 7px; border-radius: 50%; background: var(--c); } }
  & [aria-checked="true"] { background: var(--apf-assets-paper); color: var(--apf-assets-ink); font-weight: 620; box-shadow: 0 1px 2px color-mix(in oklch, var(--apf-assets-ink) 15%, transparent); }
}
.apf-assets-tags {
  display: flex; flex-wrap: wrap; gap: 5px; align-items: center;
  & span { display: inline-flex; align-items: center; gap: 4px; height: 26px; padding: 0 4px 0 9px; border-radius: 99px; background: var(--apf-assets-panel); font-size: 12px; animation: apf-assets-pop .35s var(--apf-assets-out); }
  & span button { width: 18px; height: 18px; border-radius: 50%; display: grid; place-items: center; color: var(--apf-assets-faint); &:hover { background: var(--apf-assets-line); color: var(--apf-assets-ink); } & svg { width: 10px; height: 10px; stroke-width: 2.4; } }
  & input { width: 92px; height: 26px; padding: 0 9px; border-radius: 99px; border: 1px dashed var(--apf-assets-line2); background: none; font-size: 12px; outline: none; &:focus { border-style: solid; border-color: var(--apf-assets-accent); } }
}
.apf-assets-code {
  position: relative; border-radius: 11px; background: oklch(0.21 0.02 262); color: oklch(0.9 0.01 262); overflow: hidden;
  & .apf-assets-ctabs { display: flex; gap: 2px; padding: 6px 6px 0; & button { height: 26px; padding: 0 10px; border-radius: 7px 7px 0 0; font: 600 11px/1 var(--apf-assets-mono); color: oklch(0.65 0.02 262); &[aria-selected="true"] { background: oklch(0.26 0.02 262); color: white; } } }
  & pre { margin: 0; padding: 12px 12px 14px; background: oklch(0.26 0.02 262); font: 11.5px/1.6 var(--apf-assets-mono); white-space: pre-wrap; word-break: break-all; max-height: 190px; overflow: auto; scrollbar-width: thin; }
  & .t { color: oklch(0.78 0.12 20); } & .a { color: oklch(0.82 0.1 80); } & .v { color: oklch(0.82 0.11 150); } & .p { color: oklch(0.6 0.02 262); }
  & .apf-assets-copy { position: absolute; right: 8px; top: 6px; height: 26px; padding: 0 9px; border-radius: 7px; background: oklch(0.32 0.02 262); color: white; font-size: 11.5px; font-weight: 650; display: inline-flex; align-items: center; gap: 6px; & svg { width: 13px; height: 13px; } & kbd { background: none; color: inherit; border-color: oklch(1 0 0 / .3); padding: 1px 4px 0; } &:hover { background: oklch(0.38 0.03 262); } &.is-done { background: var(--apf-assets-accent); } }
}
.apf-assets-empty { padding: 40px 6px; text-align: center; color: var(--apf-assets-mute); text-wrap: pretty; & b { display: block; color: var(--apf-assets-ink); font-size: 14px; margin-bottom: 4px; } }
.apf-assets-toast {
  position: absolute; z-index: 50; left: 50%; bottom: 16px; translate: -50% 16px; max-width: calc(100% - 32px);
  display: flex; align-items: center; gap: 14px; padding: 9px 9px 9px 16px; border-radius: 11px; background: var(--apf-assets-ink); color: var(--apf-assets-bg); font-size: 12.5px;
  box-shadow: 0 16px 34px -14px color-mix(in oklch, var(--apf-assets-ink) 70%, transparent); opacity: 0; pointer-events: none; transition: translate .45s var(--apf-assets-spring), opacity .2s;
  & [data-msg] { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }
  & button { flex: none; padding: 5px 10px; border-radius: 7px; font-weight: 700; color: color-mix(in oklch, var(--apf-assets-accent), white 50%); &:hover { background: color-mix(in oklch, var(--apf-assets-bg) 12%, transparent); } }
  &.is-on { opacity: 1; translate: -50% 0; pointer-events: auto; }
  & :focus-visible { outline-color: var(--apf-assets-bg); }
}

@container (width < 1060px) {
  .apf-assets-app { grid-template-columns: 186px minmax(0, 1fr) 290px; }
  .apf-assets-knob { width: 86px; }
}
@container (width < 960px) {
  .apf-assets-app { grid-template-columns: minmax(0, 1fr) 280px; grid-template-areas: "top insp" "main insp"; }
  .apf-assets-side {
    position: absolute; z-index: 30; left: 0; top: 0; bottom: 0; width: min(240px, 82cqi); translate: -102% 0; visibility: hidden;
    transition: translate .45s var(--apf-assets-spring), visibility 0s .45s; box-shadow: 24px 0 48px -24px color-mix(in oklch, var(--apf-assets-ink) 45%, transparent);
  }
  .apf-assets[data-nav] .apf-assets-side { translate: 0 0; visibility: visible; transition-delay: 0s; }
  .apf-assets[data-nav] .apf-assets-scrim { opacity: 1; pointer-events: auto; }
  .apf-assets-menu { display: grid; }
  .apf-assets-top { flex-wrap: wrap; }
  .apf-assets-search { flex: 1 1 calc(100% - 44px); }
}
@container (width < 760px) {
  .apf-assets-app { grid-template-columns: minmax(0, 1fr); grid-template-areas: "top" "main"; }
  .apf-assets-insp { grid-area: main; border-left: 0; border-radius: 0 0 14px 14px; display: none; }
  .apf-assets[data-screen="detail"] .apf-assets-insp { display: grid; animation: apf-assets-in .35s var(--apf-assets-out); }
