css:
@keyframes apf-finder-in { from { opacity: 0; translate: 12px 0; } }
@keyframes apf-finder-fade { from { opacity: 0; } }
@keyframes apf-finder-play { from { translate: 0 0; } to { translate: var(--run, 300px) 0; } }

.apf-finder {
  /* re-theme with these four */
  --apf-finder-bg: oklch(0.205 0.007 255);
  --apf-finder-ink: oklch(0.94 0.005 255);
  --apf-finder-accent: oklch(0.71 0.15 33);
  --apf-finder-folder: oklch(0.74 0.1 235);

  --apf-finder-panel: color-mix(in oklch, var(--apf-finder-bg), white 4%);
  --apf-finder-raise: color-mix(in oklch, var(--apf-finder-bg), white 9%);
  --apf-finder-line: color-mix(in oklch, var(--apf-finder-ink) 9%, transparent);
  --apf-finder-line2: color-mix(in oklch, var(--apf-finder-ink) 16%, transparent);
  --apf-finder-mute: color-mix(in oklch, var(--apf-finder-ink) 56%, var(--apf-finder-bg));
  --apf-finder-faint: color-mix(in oklch, var(--apf-finder-ink) 33%, var(--apf-finder-bg));
  --apf-finder-sel: color-mix(in oklch, var(--apf-finder-accent) 78%, var(--apf-finder-bg));
  --apf-finder-sel2: color-mix(in oklch, var(--apf-finder-ink) 13%, transparent);
  --apf-finder-spring: linear(0, 0.06 3%, 0.24 7.5%, 0.53 13%, 0.82 19%, 0.97 25%, 1.04 30%, 1.05 35%, 1.03 42%, 1.005 52%, 0.998 64%, 1);
  --apf-finder-out: cubic-bezier(.2, .8, .2, 1);
  --apf-finder-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;

  position: relative; width: 100%; height: var(--apf-finder-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--apf-finder-bg); color: var(--apf-finder-ink);
  font: 13px/1.35 system-ui, -apple-system, "Segoe UI", sans-serif;
  border-radius: 14px; color-scheme: dark; accent-color: var(--apf-finder-accent);
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :where(button, input) { font: inherit; color: inherit; }
  & :where(button) { cursor: default; background: none; border: 0; padding: 0; }
  & :where(svg) { fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & :focus-visible { outline: 2px solid var(--apf-finder-accent); outline-offset: 2px; }
  & kbd { font: 600 10px/1 var(--apf-finder-mono); padding: 3px 5px 2px; border-radius: 5px; border: 1px solid var(--apf-finder-line2); border-bottom-width: 2px; color: var(--apf-finder-mute); }
  & h3 { margin: 14px 0 4px; padding: 0 10px; font-size: 11px; font-weight: 650; color: var(--apf-finder-faint); }
  & .apf-finder-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
}

.apf-finder-app {
  height: 100%; display: grid; grid-template-columns: 196px minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "side top" "side main";
}

/* ── sidebar ── */
.apf-finder-side {
  grid-area: side; min-height: 0; overflow-y: auto; scrollbar-width: none; display: flex; flex-direction: column; padding: 14px 8px 12px;
  background: color-mix(in oklch, var(--apf-finder-bg), black 18%); border-right: 1px solid var(--apf-finder-line); border-radius: 14px 0 0 14px;
}
.apf-finder-lights { display: flex; gap: 8px; padding: 2px 8px 6px; & i { width: 12px; height: 12px; border-radius: 50%; background: var(--apf-finder-line2); } & i:nth-child(1) { background: oklch(0.68 0.19 25); } & i:nth-child(2) { background: oklch(0.82 0.15 85); } & i:nth-child(3) { background: oklch(0.73 0.17 145); } }
.apf-finder-favs, .apf-finder-tags { display: grid; gap: 1px; }
.apf-finder-fav {
  display: flex; align-items: center; gap: 9px; height: 28px; padding: 0 10px; border-radius: 7px; text-align: left; white-space: nowrap;
  transition: background-color .12s;
  & svg { width: 16px; height: 16px; color: var(--apf-finder-accent); flex: none; }
  & i { width: 11px; height: 11px; border-radius: 50%; background: var(--c); flex: none; margin: 0 2.5px; }
  & span { overflow: hidden; text-overflow: ellipsis; }
  & small { margin-left: auto; color: var(--apf-finder-faint); font-size: 11px; font-variant-numeric: tabular-nums; }
  &:hover { background: color-mix(in oklch, var(--apf-finder-ink) 6%, transparent); }
  &[aria-current="true"] { background: var(--apf-finder-sel2); font-weight: 600; }
  &.is-drop { background: var(--apf-finder-sel); color: white; & svg { color: white; } }
}
.apf-finder-disk {
  margin-top: auto; padding: 10px 10px 2px; font-size: 11px; color: var(--apf-finder-mute);
  & div { display: flex; justify-content: space-between; margin-bottom: 6px; } & b { font-weight: 600; color: var(--apf-finder-ink); font-variant-numeric: tabular-nums; }
  & i { display: block; height: 4px; border-radius: 9px; background: linear-gradient(90deg, var(--apf-finder-accent) var(--u, 60%), var(--apf-finder-line2) 0); }
}

/* ── toolbar ── */
.apf-finder-top { grid-area: top; display: flex; align-items: center; gap: 10px; padding: 10px 12px 10px 14px; border-bottom: 1px solid var(--apf-finder-line); min-width: 0; }
.apf-finder-icon {
  width: 30px; height: 28px; border-radius: 7px; display: grid; place-items: center; color: var(--apf-finder-mute); flex: none; transition: background-color .12s, color .12s;
  & svg { width: 18px; height: 18px; }
  &:hover:not(:disabled) { background: color-mix(in oklch, var(--apf-finder-ink) 7%, transparent); color: var(--apf-finder-ink); }
  &:disabled { opacity: .35; }
}
.apf-finder-menu { display: none; }
.apf-finder-hist { display: flex; }
.apf-finder-title { flex: 1; min-width: 0; display: flex; align-items: baseline; gap: 8px; & b { font-size: 14px; font-weight: 700; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; } & span { font-size: 12px; color: var(--apf-finder-faint); white-space: nowrap; font-variant-numeric: tabular-nums; } }
.apf-finder-acts { display: flex; gap: 2px; }
.apf-finder-search {
  display: flex; align-items: center; gap: 6px; height: 28px; width: clamp(130px, 18cqi, 210px); padding: 0 8px; border-radius: 7px; background: color-mix(in oklch, var(--apf-finder-ink) 7%, transparent);
  & svg { width: 14px; height: 14px; color: var(--apf-finder-mute); flex: none; }
  & input { flex: 1; min-width: 0; border: 0; background: none; outline: none; font-size: 12.5px; &:focus-visible { outline: none; } }
  & input::-webkit-search-cancel-button { display: none; }
  &:focus-within { box-shadow: 0 0 0 2px var(--apf-finder-accent); }
}

/* ── columns ── */
.apf-finder-main { grid-area: main; min-height: 0; min-width: 0; display: grid; grid-template-rows: minmax(0, 1fr) auto; }
.apf-finder-cols { display: flex; min-height: 0; overflow-x: auto; overflow-y: hidden; scrollbar-width: thin; overscroll-behavior-x: contain; outline: none; }
.apf-finder-col {
  position: relative; flex: 0 0 var(--w, 224px); min-width: 0; height: 100%; overflow-y: auto; padding: 4px 6px 12px; border-right: 1px solid var(--apf-finder-line);
  scrollbar-width: thin; outline: none; animation: apf-finder-in .32s var(--apf-finder-out) both;
  &.is-static { animation: none; }
}
.apf-finder-grip {
  position: sticky; float: right; top: 0; margin-right: -9px; width: 6px; height: 100%; z-index: 3; cursor: col-resize; outline: none; touch-action: none;
  &::after { content: ""; position: absolute; left: 2px; top: 0; bottom: 0; width: 2px; border-radius: 2px; background: transparent; transition: background-color .15s; }
  &:hover::after, &:focus-visible::after, &.is-on::after { background: var(--apf-finder-accent); }
}
.apf-finder-row {
  display: grid; grid-template-columns: 18px minmax(0, 1fr) auto; align-items: center; gap: 7px; height: 26px; padding: 0 6px 0 7px; border-radius: 6px; outline: none; cursor: default;
  user-select: none; -webkit-user-select: none;
  & .apf-finder-ri { width: 18px; height: 18px; display: grid; place-items: center; color: var(--k, var(--apf-finder-mute)); & svg { width: 17px; height: 17px; } }
  & .apf-finder-rn { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & .apf-finder-rn mark { background: color-mix(in oklch, var(--apf-finder-accent) 35%, transparent); color: inherit; border-radius: 2px; }
  & .apf-finder-rt { display: flex; align-items: center; gap: 0; }
  & .apf-finder-rt i { width: 8px; height: 8px; border-radius: 50%; background: var(--c); margin-left: -3px; box-shadow: 0 0 0 1.5px var(--apf-finder-bg); }
  & .apf-finder-chev { width: 12px; height: 12px; color: var(--apf-finder-faint); }
  &:hover { background: color-mix(in oklch, var(--apf-finder-ink) 5%, transparent); }
  &.is-path { background: var(--apf-finder-sel2); }
  &[aria-selected="true"] { background: var(--apf-finder-sel2); }
  &.is-drop { background: var(--apf-finder-sel); color: white; & .apf-finder-ri, & .apf-finder-chev { color: white; } }
  &.is-lifted { opacity: .4; }
  &.is-new { animation: apf-finder-fade .4s var(--apf-finder-out); }
}
.apf-finder-col.is-active .apf-finder-row[aria-selected="true"] { background: var(--apf-finder-sel); color: white; & .apf-finder-ri, & .apf-finder-chev { color: white; } & .apf-finder-rt i { box-shadow: 0 0 0 1.5px var(--apf-finder-sel); } }
.apf-finder-col.is-active .apf-finder-row:focus-visible { outline: 2px solid color-mix(in oklch, white 70%, transparent); outline-offset: -2px; }
.apf-finder [data-kind="folder"] { --k: var(--apf-finder-folder); }
.apf-finder [data-kind="image"] { --k: oklch(0.75 0.12 330); }
