.apf-finder-ren { width: 100%; height: 22px; padding: 0 5px; border-radius: 4px; border: 0; outline: 2px solid var(--apf-finder-accent); background: var(--apf-finder-bg); color: var(--apf-finder-ink); font-size: 13px; }
.apf-finder-empty { padding: 20px 10px; color: var(--apf-finder-faint); font-size: 12px; text-align: center; }

/* preview column */
.apf-finder-prev {
