  & .apf-finder-thumb > svg { width: 100%; height: 100%; }
  & .apf-finder-thumb.is-art { border-radius: 8px; overflow: hidden; box-shadow: 0 16px 34px -18px oklch(0 0 0 / .8); aspect-ratio: auto; }
  & h4 { margin: 0 0 2px; font-size: 14px; font-weight: 700; overflow-wrap: anywhere; text-wrap: balance; }
  & .apf-finder-kind { margin: 0 0 14px; font-size: 12px; color: var(--apf-finder-mute); }
  & dl { width: 100%; max-width: 300px; margin: 0; display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 6px 12px; font-size: 12px; text-align: left; border-top: 1px solid var(--apf-finder-line); padding-top: 12px; }
  & dt { color: var(--apf-finder-faint); text-align: right; }
  & dd { margin: 0; font-variant-numeric: tabular-nums; overflow-wrap: anywhere; }
  & .apf-finder-ptags { display: flex; flex-wrap: wrap; gap: 4px; justify-content: center; margin-top: 14px; }
  & .apf-finder-ptags button { display: inline-flex; align-items: center; gap: 5px; height: 24px; padding: 0 8px; border-radius: 99px; font-size: 11.5px; border: 1px solid var(--apf-finder-line2); color: var(--apf-finder-mute); cursor: pointer; transition: background-color .15s, color .15s; }
  & .apf-finder-ptags button i { width: 8px; height: 8px; border-radius: 50%; background: var(--c); }
  & .apf-finder-ptags button[aria-pressed="true"] { background: color-mix(in oklch, var(--c) 22%, transparent); border-color: color-mix(in oklch, var(--c) 50%, transparent); color: var(--apf-finder-ink); }
  & .apf-finder-hint { margin-top: auto; padding-top: 16px; font-size: 11.5px; color: var(--apf-finder-faint); }
}
.apf-finder-path {
  display: flex; align-items: center; gap: 3px; padding: 6px 12px; border-top: 1px solid var(--apf-finder-line); font-size: 11.5px; color: var(--apf-finder-mute); overflow: hidden; white-space: nowrap;
  & button { display: inline-flex; align-items: center; gap: 4px; padding: 2px 5px; border-radius: 5px; & svg { width: 13px; height: 13px; color: var(--k, var(--apf-finder-folder)); } &:hover { background: color-mix(in oklch, var(--apf-finder-ink) 7%, transparent); color: var(--apf-finder-ink); } }
