}
.apf-finder-scrim { position: absolute; inset: 0; z-index: 20; background: oklch(0 0 0 / .45); opacity: 0; pointer-events: none; transition: opacity .3s; }

@container (width < 960px) {
  .apf-finder-app { grid-template-columns: 168px minmax(0, 1fr); }
  .apf-finder-path .apf-finder-keys { display: none; }
  .apf-finder-acts [data-act="newfolder"] { display: none; }
}
@container (width < 760px) {
  .apf-finder-app { grid-template-columns: minmax(0, 1fr); grid-template-areas: "top" "main"; }
  .apf-finder-side { position: absolute; z-index: 30; top: 0; bottom: 0; left: 0; width: min(230px, 78cqi); translate: -102% 0; visibility: hidden; transition: translate .45s var(--apf-finder-spring), visibility 0s .45s; }
  .apf-finder[data-nav] .apf-finder-side { translate: 0 0; visibility: visible; transition-delay: 0s; }
  .apf-finder[data-nav] .apf-finder-scrim { opacity: 1; pointer-events: auto; }
  .apf-finder-menu { display: grid; }
  .apf-finder-top { flex-wrap: wrap; gap: 6px; }
  .apf-finder-title { order: -1; flex: 1 1 calc(100% - 80px); }
  .apf-finder-search { flex: 1; width: auto; }
  /* one column at a time: only the active column (or the preview) shows */
  .apf-finder-cols { overflow: hidden; }
  .apf-finder-col, .apf-finder-prev { display: none; flex: 1 1 100%; min-width: 0; border-right: 0; }
  .apf-finder-col.is-only, .apf-finder-prev.is-only { display: block; }
  .apf-finder-prev.is-only { display: flex; }
  .apf-finder-grip { display: none; }
  .apf-finder-row { height: 38px; font-size: 14px; }
  .apf-finder-ql { padding: 12px; }
}

@media (prefers-reduced-motion: reduce) {
  .apf-finder *, .apf-finder *::before, .apf-finder *::after {
    animation-duration: .01ms !important; animation-iteration-count: 1 !important; animation-delay: 0s !important;
    transition-duration: .01ms !important; transition-delay: 0s !important;
  }
  .apf-finder-qlbody .apf-finder-head { animation-duration: var(--dur, 42s) !important; }
}

